def _latest_ledger_run_id(
    con: sqlite3.Connection,
    segment_state_run_id: int | None = None,
) -> int:
    if not _table_exists(con, "ml_issue_ledger_runs"):
        return 0
    row = _one(
        con,
        """
        SELECT id
        FROM ml_issue_ledger_runs
        WHERE finished_at IS NOT NULL
          AND (? IS NULL OR segment_state_run_id = ?)
        ORDER BY finished_at DESC, id DESC
        LIMIT 1
        """,
        (segment_state_run_id, segment_state_run_id),
    )
    return _int(row.get("id"))


def _latest_segment_state_summary(con: sqlite3.Connection) -> dict[str, Any]:
    if not _table_exists(con, "segment_state_runs"):
        return {
            "run_id": 0,
            "total_segments": 0,
            "closed_count": 0,
            "pending_count": 0,
            "needs_apply": 0,
            "closed_rate": 0,
            "finished_at": "",
        }
    row = _one(
        con,
        """
        SELECT id, total_segments, closed_count, pending_count, output_apply_pending_count, finished_at
        FROM segment_state_runs
        WHERE finished_at IS NOT NULL
          AND total_segments > 1000
        ORDER BY finished_at DESC, id DESC
        LIMIT 1
        """,
    )
    total = _int(row.get("total_segments")) or (_int(row.get("closed_count")) + _int(row.get("pending_count")))
    return {
        "run_id": _int(row.get("id")),
        "total_segments": total,
        "closed_count": _int(row.get("closed_count")),
        "pending_count": _int(row.get("pending_count")),
        "needs_apply": _int(row.get("output_apply_pending_count")),
        "closed_rate": _pct(row.get("closed_count"), total),
        "finished_at": row.get("finished_at") or "",
    }


def _last_production_delta_payload(
    con: sqlite3.Connection,
    run: dict[str, Any],
    current_segment_state: dict[str, Any],
) -> dict[str, Any]:
    if not (_table_exists(con, "segment_state_runs") and isinstance(run, dict) and run.get("finished_at")):
        return {"available": False, "reason": "pending_instrumentation"}

    baseline = _one(
        con,
        """
        SELECT id, total_segments, closed_count, pending_count, output_apply_pending_count, finished_at
        FROM segment_state_runs
        WHERE finished_at IS NOT NULL
          AND total_segments > 1000
          AND finished_at <= ?
        ORDER BY finished_at DESC, id DESC
        LIMIT 1
        """,
        (run.get("finished_at"),),
    )
    if not baseline:
        return {
            "available": False,
            "reason": "baseline_not_found",
            "last_production_run_id": run.get("run_id") or "",
            "last_production_finished_at": run.get("finished_at") or "",
        }

    baseline_closed = _int(baseline.get("closed_count"))
    baseline_pending = _int(baseline.get("pending_count"))
    baseline_needs_apply = _int(baseline.get("output_apply_pending_count"))
    current_closed = _int(current_segment_state.get("closed_count"))
    current_pending = _int(current_segment_state.get("pending_count"))
    current_needs_apply = _int(current_segment_state.get("needs_apply"))

    return {
        "available": True,
        "last_production_run_id": run.get("run_id") or "",
        "last_production_finished_at": run.get("finished_at") or "",
        "baseline_segment_state_run_id": _int(baseline.get("id")),
        "baseline_finished_at": baseline.get("finished_at") or "",
        "closed_delta": current_closed - baseline_closed,
        "pending_delta": current_pending - baseline_pending,
        "needs_apply_delta": current_needs_apply - baseline_needs_apply,
        "current_segment_state_run_id": _int(current_segment_state.get("run_id")),
    }


def _segment_state_trend(con: sqlite3.Connection, limit: int = 12) -> list[dict[str, Any]]:
    if not _table_exists(con, "segment_state_runs"):
        return []
    rows = _all(
        con,
        """
        SELECT id, total_segments, closed_count, pending_count, output_apply_pending_count, finished_at
        FROM segment_state_runs
        WHERE finished_at IS NOT NULL
          AND total_segments > 1000
        ORDER BY finished_at DESC, id DESC
        LIMIT ?
        """,
        (limit,),
    )
    trend = []
    for row in reversed(rows):
        total = _int(row.get("total_segments")) or (_int(row.get("closed_count")) + _int(row.get("pending_count")))
        trend.append(
            {
                "run_id": _int(row.get("id")),
                "total_segments": total,
                "closed_count": _int(row.get("closed_count")),
                "pending_count": _int(row.get("pending_count")),
                "needs_apply": _int(row.get("output_apply_pending_count")),
                "closed_rate": _pct(row.get("closed_count"), total),
                "finished_at": row.get("finished_at") or "",
            }
        )
    return trend


def _output_coverage(con: sqlite3.Connection) -> float:
    if not (_table_exists(con, "source_segments") and _table_exists(con, "output_segments")):
        return 0
    row = _one(
        con,
        """
        SELECT
          COUNT(*) AS total,
          SUM(CASE WHEN COALESCE(o.portuguese_text, '') <> '' THEN 1 ELSE 0 END) AS with_output
        FROM source_segments s
        LEFT JOIN output_segments o ON o.segment_id = s.id
        WHERE s.is_active = 1
        """,
    )
    return _pct(row.get("with_output"), row.get("total"))


def _cache_stage_compact(stages: list[dict[str, Any]]) -> list[dict[str, Any]]:
    result = []
    for stage in stages:
        if not isinstance(stage, dict):
            continue
        result.append(
            {
                "id": stage.get("id"),
                "label": stage.get("label"),
                "status": stage.get("status"),
                "started_at": stage.get("started_at"),
                "updated_at": stage.get("updated_at"),
                "finished_at": stage.get("finished_at"),
                "exit_code": stage.get("exit_code"),
                "progress_pct": stage.get("progress_pct"),
                "log_line_count": stage.get("log_line_count"),
                "heartbeat_at": stage.get("heartbeat_at"),
                "metrics": stage.get("metrics") or {},
            }
        )
    return result


def _production_run_progress(run: dict[str, Any], stages: list[dict[str, Any]]) -> int:
    """Calcula o progresso agregado sem depender do snapshot pesado do dashboard."""
    if run.get("status") == "completed":
        return 100
    if not stages:
        return 0

    done_stages = sum(1 for stage in stages if isinstance(stage, dict) and stage.get("status") == "done")
    running_stage = next(
        (stage for stage in stages if isinstance(stage, dict) and stage.get("status") == "running"),
        None,
    )
    running_progress = 0.0
    if running_stage:
        try:
            running_progress = min(90.0, max(0.0, float(running_stage.get("progress_pct") or 0))) / 100.0
        except (TypeError, ValueError):
            running_progress = 0.0
    return round(((done_stages + running_progress) / len(stages)) * 100)


def _production_run_for_current_state(
    app_state: dict[str, Any],
    run: dict[str, Any],
) -> tuple[dict[str, Any], dict[str, Any] | None]:
    """Separa uma falha historica do estado operacional ja reconciliado.

    A run gravada em disco e um registro historico imutavel. Depois de uma
    recuperacao manual/automatica, um segment-state mais novo pode provar que
    todos os itens foram fechados. Nesse caso o dashboard recebe uma run
    sintetica concluida e mantem a falha original em ``last_failed_run``.
    """
    if run.get("status") != "failed":
        return run, None

    validation = run.get("publication_closure_validation")
    validation = validation if isinstance(validation, dict) else {}
    failure = run.get("failure")
    failure = failure if isinstance(failure, dict) else {}
    failure_message = str(failure.get("message") or run.get("message") or "")
    blocked_ids = [
        _int(segment_id)
        for segment_id in (validation.get("blocked_ids") or [])
        if _int(segment_id) > 0
    ]
    is_publication_closure_failure = bool(blocked_ids) and (
        "lifecycle closure mismatch" in failure_message.lower()
        or run.get("failed_stage") in {"segment_state_after", "segment_state_after_write"}
        or failure.get("stage") in {"segment_state_after", "segment_state_after_write"}
    )
    if not is_publication_closure_failure:
        return run, None

    release = app_state.get("release")
    release = release if isinstance(release, dict) else {}
    closure = release.get("operational_closure")
    closure = closure if isinstance(closure, dict) else {}
    failed_state_run_id = (
        _int(validation.get("segment_state_run_id"))
        or _int(run.get("new_segment_state_run_id"))
        or _int(run.get("segment_state_run_id"))
    )
    current_state_run_id = (
        _int(release.get("latest_segment_state_run_id"))
        or _int(closure.get("segment_state_run_id"))
    )
    pending_count = _int(release.get("pending_count"), _int(closure.get("pending_count")))
    needs_apply = _int(release.get("needs_apply"), _int(closure.get("needs_apply")))
    state_is_closed = closure.get("is_closed") is True or (
        release.get("readiness") == "ready_for_release"
        and pending_count == 0
        and needs_apply == 0
    )
    if (
        not failed_state_run_id
        or current_state_run_id <= failed_state_run_id
        or not state_is_closed
        or pending_count != 0
        or needs_apply != 0
    ):
        return run, None

    post_release = release.get("post_release")
    post_release = post_release if isinstance(post_release, dict) else {}
    diff_review = post_release.get("diff_review")
    diff_review = diff_review if isinstance(diff_review, dict) else {}
    diff_summary = diff_review.get("summary")
    diff_summary = diff_summary if isinstance(diff_summary, dict) else {}
    package_diff_count = _int(
        diff_summary.get("package_diff_count"),
        _int(diff_summary.get("raw_output_diff_count"), _int(diff_summary.get("changed_vs_old"))),
    )
    reconciled_at = str((app_state.get("cache") or {}).get("generated_at") or _now_iso())
    next_action = "materialize_version" if package_diff_count > 0 else "await_new_applies"
    next_action_message = (
        f"Apply zerado; {package_diff_count} alteracoes prontas para materializar."
        if package_diff_count > 0
        else "Apply e pacote zerados; aguardando novas promocoes confirmadas."
    )
    stage_specs = (
        ("publication_preflight", "Preflight publicavel"),
        ("apply_confirmed_write", "Apply confirmado"),
        ("segment_state_after_write", "Validacao reconciliada"),
        ("production_report", "Relatorio final"),
    )
    stages = [
        {
            "id": stage_id,
            "label": label,
            "status": "done",
            "started_at": reconciled_at,
            "updated_at": reconciled_at,
            "finished_at": reconciled_at,
            "exit_code": 0,
            "progress_pct": 100,
            "metrics": {
                "segment_state_run_id": current_state_run_id,
                "reconciled_run_id": run.get("run_id"),
            },
        }
        for stage_id, label in stage_specs
    ]
    reconciliation = {
        "status": "resolved",
        "run_id": run.get("run_id"),
        "reconciled_at": reconciled_at,
        "reason": "newer_segment_state_closed",
        "failed_segment_state_run_id": failed_state_run_id,
        "current_segment_state_run_id": current_state_run_id,
        "blocked_ids": blocked_ids,
        "pending_count": pending_count,
        "needs_apply": needs_apply,
        "package_diff_count": package_diff_count,
        "next_action": next_action,
    }
    display_run = {
        "run_id": f"{run.get('run_id')}-reconciled-{current_state_run_id}",
        "status": "completed",
        "mode": "publication_apply_reconciled",
        "run_mode": "publication",
        "started_at": run.get("started_at") or reconciled_at,
        "updated_at": reconciled_at,
        "finished_at": reconciled_at,
        "current_stage": "production_report",
        "current_label": "Estado reconciliado",
        "stages": stages,
        "message": (
            f"A falha da run {run.get('run_id')} foi reconciliada pelo "
            f"segment-state #{current_state_run_id}. {next_action_message}"
        ),
        "new_segment_state_run_id": current_state_run_id,
        "output_changed": bool(run.get("output_changed")),
        "output_written_count": _int(run.get("output_written_count")),
        "materialization_started": False,
        "next_action": next_action,
        "reconciled": True,
        "reconciliation": reconciliation,
        "last_failed_run": run,
        "historical_failure": {
            "run_id": run.get("run_id"),
            "status": run.get("status"),
            "failed_stage": run.get("failed_stage") or failure.get("stage"),
            "message": failure_message,
            "finished_at": run.get("finished_at"),
        },
    }
    return display_run, reconciliation


def _pending_by_family_payload(con: sqlite3.Connection, segment_state_run_id: int | None) -> list[dict[str, Any]]:
    ledger_run_id = _latest_ledger_run_id(con, segment_state_run_id)
    if not segment_state_run_id or not ledger_run_id:
        return []
    if not (_table_exists(con, "segment_state_items") and _table_exists(con, "ml_issue_ledger_items")):
        return []
    return _all(
        con,
        """
        SELECT
          COALESCE(NULLIF(issue_family, ''), 'unknown') AS label,
          COUNT(DISTINCT segment_id) AS value
        FROM ml_issue_ledger_items
        WHERE run_id = ?
          AND state_group = 'pending'
          AND COALESCE(status, 'open') = 'open'
        GROUP BY COALESCE(NULLIF(issue_family, ''), 'unknown')
        ORDER BY value DESC, label
        LIMIT 8
        """,
        (ledger_run_id,),
    )


def _package_versions_payload(con: sqlite3.Connection) -> list[dict[str, Any]]:
    if not _table_exists(con, "package_versions"):
        return []
    versions = _all(
        con,
        """
        SELECT
          id,
          version_number,
          version_label,
          package_name,
          package_role,
          parent_version_id,
          file_count,
          segment_count,
          measured_score_count,
          full_average_score,
          change_cohort_score,
          change_cohort_delta,
          changed_from_parent_count,
          segment_state_run_id,
          score_run_id,
          score_rule_version,
          closed_count,
          pending_count,
          needs_output_apply_count,
          status,
          frozen_at
        FROM package_versions
        ORDER BY version_number
        """,
    )
    if not versions or not _table_exists(con, "package_version_items"):
        return versions

    # V1/V2 used a partial measurement population and are intentionally omitted
    # from the overview trend. Aggregate only full-package snapshots (V3+) and
    # cache them because version rows are immutable after materialization.
    comparable_versions = [row for row in versions if _int(row.get("version_number")) >= 3]
    cache_key = tuple(
        (_int(row.get("id")), _int(row.get("measured_score_count")))
        for row in comparable_versions
    )
    with PACKAGE_VERSION_BANDS_LOCK:
        if PACKAGE_VERSION_BANDS_CACHE.get("key") != cache_key:
            version_ids = [version_id for version_id, _ in cache_key if version_id]
            band_items: dict[int, dict[str, int]] = {}
            if version_ids:
                placeholders = ", ".join("?" for _ in version_ids)
                rows = _all(
                    con,
                    f"""
                    SELECT
                      version_id,
                      COUNT(score) AS measured,
                      SUM(CASE WHEN score < 0.20 THEN 1 ELSE 0 END) AS critical,
                      SUM(CASE WHEN score >= 0.20 AND score < 0.50 THEN 1 ELSE 0 END) AS low,
                      SUM(CASE WHEN score >= 0.50 AND score < 0.75 THEN 1 ELSE 0 END) AS moderate,
                      SUM(CASE WHEN score >= 0.75 AND score < 0.90 THEN 1 ELSE 0 END) AS good,
                      SUM(CASE WHEN score >= 0.90 THEN 1 ELSE 0 END) AS high
                    FROM package_version_items
                    WHERE version_id IN ({placeholders})
                    GROUP BY version_id
                    """,
                    tuple(version_ids),
                )
                for row in rows:
                    version_id = _int(row.get("version_id"))
                    version = next(
                        (item for item in comparable_versions if _int(item.get("id")) == version_id),
                        {},
                    )
                    measured = _int(row.get("measured"))
                    band_items[version_id] = {
                        "critical": _int(row.get("critical")),
                        "low": _int(row.get("low")),
                        "moderate": _int(row.get("moderate")),
                        "good": _int(row.get("good")),
                        "high": _int(row.get("high")),
                        "unmeasured": max(0, _int(version.get("segment_count")) - measured),
                    }
            PACKAGE_VERSION_BANDS_CACHE["key"] = cache_key
            PACKAGE_VERSION_BANDS_CACHE["items"] = band_items
        cached_bands = dict(PACKAGE_VERSION_BANDS_CACHE.get("items") or {})

    for version in versions:
        version["quality_bands"] = cached_bands.get(_int(version.get("id")))
    return versions


def _quality_hotspots_payload(con: sqlite3.Connection) -> list[dict[str, Any]]:
    if not _table_exists(con, "ml_score_items"):
        return []
    latest_score_run = _latest_score(con, operational=True) or _latest_score(con)
    latest_score_run_id = _int(latest_score_run.get("id"))
    if not latest_score_run_id:
        return []
    with QUALITY_HOTSPOTS_LOCK:
        if QUALITY_HOTSPOTS_CACHE.get("score_run_id") == latest_score_run_id:
            return list(QUALITY_HOTSPOTS_CACHE.get("items") or [])
        items = _all(
            con,
            """
            WITH scored AS (
              SELECT
                CASE
                  WHEN instr(score.relative_path, '/') > 0
                  THEN substr(score.relative_path, 1, instr(score.relative_path, '/') - 1)
                  ELSE COALESCE(NULLIF(score.relative_path, ''), 'root')
                END AS area,
                score.model_safe_probability AS score
              FROM ml_score_items score
              WHERE score.run_id = ?
                AND score.model_safe_probability IS NOT NULL
            )
            SELECT
              area AS label,
              COUNT(*) AS measured_count,
              SUM(CASE WHEN score < 0.20 THEN 1 ELSE 0 END) AS critical_count,
              SUM(CASE WHEN score >= 0.20 AND score < 0.50 THEN 1 ELSE 0 END) AS low_count,
              SUM(CASE WHEN score < 0.50 THEN 1 ELSE 0 END) AS attention_count,
              AVG(score) AS average_score
            FROM scored
            GROUP BY area
            HAVING attention_count > 0
            ORDER BY attention_count DESC, critical_count DESC, area
            LIMIT 8
            """,
            (latest_score_run_id,),
        )
        QUALITY_HOTSPOTS_CACHE["score_run_id"] = latest_score_run_id
        QUALITY_HOTSPOTS_CACHE["items"] = items
        return list(items)


def _quality_pattern_discovery_payload(con: sqlite3.Connection) -> dict[str, Any]:
    required_tables = {
        "ml_quality_pattern_discovery_runs",
        "ml_quality_pattern_families",
        "ml_quality_pattern_observations",
    }
    if not all(_table_exists(con, table_name) for table_name in required_tables):
        return {"instrumented": False, "families": []}
    run = _one(
        con,
        """
        SELECT id AS run_id, run_key, rule_version, quality_epoch_id, score_run_id,
               low_score_threshold, active_segment_count, evidence_segment_count,
               family_count, new_family_count, recurring_family_count,
               covered_family_count, actionable_family_count,
               ignored_score_only_count, status, summary_json, finished_at, updated_at
        FROM ml_quality_pattern_discovery_runs
        WHERE status = 'completed'
        ORDER BY id DESC
        LIMIT 1
        """,
    )
    run_id = _int(run.get("run_id"))
    if not run_id:
        return {"instrumented": True, "families": []}
    try:
        run_summary = json.loads(run.get("summary_json") or "{}")
    except (TypeError, json.JSONDecodeError):
        run_summary = {}
    if isinstance(run_summary, dict):
        for key in (
            "monitoring_family_count",
            "closed_family_count",
            "audit_blind_spot_count",
        ):
            if key in run_summary:
                run[key] = run_summary[key]
    run.pop("summary_json", None)
    families = _all(
        con,
        """
        SELECT family.id, family.family_key, family.evidence_kind,
               family.issue_type, family.token_context, family.file_family,
               family.text_relation, family.provider_id, family.evidence_type,
               family.observation_count, observation.status,
               observation.segment_count, observation.occurrence_count,
               observation.low_score_count, observation.low_score_share,
               observation.active_package_share, observation.average_score,
               observation.minimum_score, observation.maximum_score,
               observation.severity, observation.confidence,
               observation.novelty, observation.reach, observation.priority,
               observation.samples_json, observation.metrics_json
        FROM ml_quality_pattern_observations observation
        JOIN ml_quality_pattern_families family ON family.id = observation.family_id
        WHERE observation.run_id = ?
        ORDER BY observation.priority DESC, observation.segment_count DESC, family.id
        LIMIT 120
        """,
        (run_id,),
    )
    for family in families:
        try:
            samples = json.loads(family.get("samples_json") or "[]")
        except (TypeError, json.JSONDecodeError):
            samples = []
        family["samples"] = samples if isinstance(samples, list) else []
        family.pop("samples_json", None)
        try:
            metrics = json.loads(family.get("metrics_json") or "{}")
        except (TypeError, json.JSONDecodeError):
            metrics = {}
        if isinstance(metrics, dict):
            for key in (
                "operational_segment_count",
                "closed_segment_count",
                "lifecycle_observed_count",
            ):
                if key in metrics:
                    family[key] = metrics[key]
        family.pop("metrics_json", None)

    segment_ids = sorted(
        {
            _int(sample.get("segment_id"))
            for family in families
            for sample in family.get("samples") or []
            if isinstance(sample, dict) and _int(sample.get("segment_id"))
        }
    )
    segment_context_by_id: dict[int, dict[str, Any]] = {}
    if segment_ids:
        discovery_score_contract = _operational_effective_score_contract(
            con,
            _int(run.get("score_run_id")),
        )
        discovery_calibration_run_id = (
            _int(discovery_score_contract.get("candidate_run_id"))
            if discovery_score_contract.get("active")
            else 0
        )
        discovery_calibration_join = (
            "LEFT JOIN ml_score_calibration_candidate_items calibrated "
            "ON calibrated.run_id = ? AND calibrated.segment_id = source.id"
            if discovery_calibration_run_id
            else ""
        )
        discovery_raw_score_sql = (
            "score.model_safe_probability"
            if "model_safe_probability" in _table_columns(con, "ml_score_items")
            else "NULL"
        )
        discovery_score_select = (
            "calibrated.candidate_probability AS effective_score, "
            f"{discovery_raw_score_sql} AS raw_score"
            if discovery_calibration_run_id
            else f"{discovery_raw_score_sql} AS effective_score, {discovery_raw_score_sql} AS raw_score"
        )
        placeholders = ", ".join("?" for _ in segment_ids)
        segment_context_by_id = {
            _int(row.get("segment_id")): row
            for row in _all(
                con,
                f"""
                SELECT source.id AS segment_id, source.relative_path,
                       source.source_key, source.english_text,
                       source.spanish_text, source.old_text,
                       output.portuguese_text AS output_text,
                       score.candidate_text AS score_candidate_text,
                       {discovery_score_select}
                FROM source_segments source
                LEFT JOIN output_segments output ON output.segment_id = source.id
                LEFT JOIN ml_score_items score
                  ON score.segment_id = source.id AND score.run_id = ?
                {discovery_calibration_join}
                WHERE source.id IN ({placeholders})
                """,
                (
                    _int(run.get("score_run_id")),
                    *((discovery_calibration_run_id,) if discovery_calibration_run_id else ()),
                    *segment_ids,
                ),
            )
        }

    discovery_review_lookup = _regenerative_review_lookup(con, "discovery")
    discovery_batch_count = 0
    for family in families:
        pattern_guidance = _discovery_pattern_guidance(
            family.get("issue_type"),
            family.get("token_context"),
            family.get("file_family"),
        )
        family["pattern_guidance"] = pattern_guidance
        reviewed_samples: list[dict[str, Any]] = []
        for sample_index, sample in enumerate(family["samples"]):
            if not isinstance(sample, dict):
                continue
            segment_id = _int(sample.get("segment_id"))
            context = segment_context_by_id.get(segment_id, {})
            for key in (
                "relative_path",
                "source_key",
                "english_text",
                "spanish_text",
                "old_text",
                "output_text",
            ):
                if not sample.get(key) and context.get(key) is not None:
                    sample[key] = context[key]
            if context.get("score_candidate_text") is not None:
                sample["candidate_text"] = context["score_candidate_text"]
            if context.get("effective_score") is not None:
                sample["raw_score"] = context.get("raw_score")
                sample["effective_score"] = context.get("effective_score")
                sample["score"] = context.get("effective_score")
                sample["effective_score_source"] = (
                    "operational_calibrated_score"
                    if discovery_calibration_run_id
                    else "raw_model"
                )
            # Display-only guidance stays outside evidence so wording changes do not
            # invalidate hashes or reopen previously recorded human decisions.
            sample["pattern_guidance"] = pattern_guidance
            sample_identity = f"segment:{segment_id}" if segment_id else f"sample:{sample_index}"
            item_key = f"family:{family.get('family_key')}:{sample_identity}"
            candidate_text = str(
                sample.get("candidate_text")
                or sample.get("output_text")
                or ""
            )
            evidence = {
                "family_key": str(family.get("family_key") or ""),
                "segment_id": segment_id,
                "candidate_hash": hashlib.sha256(
                    candidate_text.encode("utf-8")
                ).hexdigest(),
                "issue_type": str(family.get("issue_type") or ""),
                "token_context": str(family.get("token_context") or ""),
                "file_family": str(family.get("file_family") or ""),
                "evidence_kind": str(family.get("evidence_kind") or ""),
                "score": sample.get("score"),
            }
            reviewed_samples.append(
                _attach_regenerative_review_contract(
                    sample,
                    queue_type="discovery",
                    item_key=item_key,
                    snapshot_id=run_id,
                    evidence=evidence,
                    decisions_by_evidence=discovery_review_lookup,
                )
            )
        family["samples"] = reviewed_samples
        decisions = [
            str(sample.get("review_decision") or "")
            for sample in reviewed_samples
            if isinstance(sample, dict) and sample.get("review_status") == "reviewed"
        ]
        supports = decisions.count("supports_pattern")
        contradicts = decisions.count("contradicts_pattern")
        boundaries = decisions.count("boundary_case")
        issue_signal = (
            f"{family.get('issue_type') or ''} {family.get('token_context') or ''}"
        ).casefold()
        if any(
            token in issue_signal
            for token in ("punctuation", "angular_quote", "guillemet", "aspas")
        ):
            lane_id, lane_label = "ptbr_punctuation", "Aspas e pontuação PT-BR"
        elif any(
            token in issue_signal
            for token in ("spanish", "espanhol", "untranslated", "residual")
        ):
            lane_id, lane_label = "spanish_residual", "Espanhol residual"
        elif any(
            token in issue_signal
            for token in ("mojibake", "unicode", "encoding", "garbled")
        ):
            lane_id, lane_label = "mojibake_unicode", "Unicode / mojibake"
        elif any(
            token in issue_signal
            for token in (
                "gender",
                "genero",
                "article",
                "pronoun",
                "meu",
                "minha",
                "seu",
                "sua",
            )
        ):
            lane_id, lane_label = (
                "dynamic_gender",
                "Gênero e concordância dinâmica",
            )
        elif any(
            token in issue_signal
            for token in (
                "token",
                "structure",
                "syntax",
                "boundary",
                "bracket",
                "quote",
                "escape",
            )
        ):
            lane_id, lane_label = "structure_tokens", "Estrutura e tokens"
        elif "glossary" in issue_signal:
            lane_id, lane_label = "glossary_terms", "Glossário e termos"
        else:
            lane_id, lane_label = "other_patterns", "Outros padrões confirmados"
        required_confirmations = _discovery_required_confirmation_count(family)
        if supports >= required_confirmations and supports > max(contradicts, boundaries):
            routing_status = (
                "ready_with_boundary_guard"
                if boundaries
                else "ready_for_correction"
            )
        elif contradicts >= required_confirmations and contradicts > max(supports, boundaries):
            routing_status = "rejected_by_human_evidence"
        elif boundaries >= required_confirmations and boundaries >= max(supports, contradicts):
            routing_status = "boundary_only"
        else:
            routing_status = "awaiting_review"
        pending_samples = [
            sample
            for sample in reviewed_samples
            if sample.get("review_status") == "pending"
        ]
        selected_representative: dict[str, Any] | None = None
        if routing_status == "awaiting_review" and pending_samples:
            if discovery_batch_count < REGENERATIVE_REVIEW_BATCH_LIMIT:
                selected_representative = pending_samples[0]
                discovery_batch_count += 1
            for sample in pending_samples:
                contract = sample.get("review_contract") or {}
                if sample is selected_representative:
                    contract["representative"] = True
                    contract["representative_rank"] = len(decisions) + 1
                    contract["required_confirmations"] = required_confirmations
                else:
                    contract["available"] = False
                    contract["representative"] = False
                    contract["reason"] = (
                        "batch_limit"
                        if discovery_batch_count >= REGENERATIVE_REVIEW_BATCH_LIMIT
                        and selected_representative is None
                        else "waiting_for_family_representative"
                    )
                sample["review_contract"] = contract
                if sample is not selected_representative:
                    sample["review_status"] = "not_selected"
        else:
            for sample in pending_samples:
                contract = sample.get("review_contract") or {}
                contract["available"] = False
                contract["representative"] = False
                contract["reason"] = "family_decision_complete"
                sample["review_contract"] = contract
                sample["review_status"] = "not_selected"
        family["human_review"] = {
            "reviewed_count": len(decisions),
            "supports_pattern": supports,
            "contradicts_pattern": contradicts,
            "boundary_case": boundaries,
            "required_confirmations": required_confirmations,
            "next_representative_segment_id": (
                _int(selected_representative.get("segment_id"))
                if selected_representative
                else None
            ),
        }
        family["representative_policy"] = {
            "mode": "progressive_family_review",
            "visible_at_once": 1,
            "required_confirmations": required_confirmations,
            "sample_count": len(reviewed_samples),
            "decision_complete": routing_status != "awaiting_review",
        }
        family["routing_status"] = routing_status
        family["correction_lane"] = {
            "id": lane_id,
            "label": lane_label,
        }
    sample_rows = [
        sample
        for family in families
        for sample in family.get("samples") or []
        if isinstance(sample, dict) and sample.get("review_contract", {}).get("available")
    ]
    lane_rows: dict[str, dict[str, Any]] = {}
    for family in families:
        lane = family.get("correction_lane") or {}
        lane_id = str(lane.get("id") or "other_patterns")
        row = lane_rows.setdefault(
            lane_id,
            {
                "id": lane_id,
                "label": lane.get("label") or lane_id.replace("_", " "),
                "family_count": 0,
                "segment_count": 0,
                "ready_segment_count": 0,
                "ready_family_count": 0,
                "boundary_family_count": 0,
                "rejected_family_count": 0,
                "pending_family_count": 0,
            },
        )
        row["family_count"] += 1
        row["segment_count"] += _int(family.get("segment_count"))
        status = str(family.get("routing_status") or "awaiting_review")
        if status in {"ready_for_correction", "ready_with_boundary_guard"}:
            row["ready_family_count"] += 1
            row["ready_segment_count"] += _int(family.get("segment_count"))
        elif status == "boundary_only":
            row["boundary_family_count"] += 1
        elif status == "rejected_by_human_evidence":
            row["rejected_family_count"] += 1
        else:
            row["pending_family_count"] += 1
    correction_lanes = sorted(
        lane_rows.values(),
        key=lambda item: (
            -_int(item.get("ready_family_count")),
            -_int(item.get("segment_count")),
            str(item.get("label") or ""),
        ),
    )
    return {
        "instrumented": True,
        **run,
        "review_pending_count": sum(
            1 for sample in sample_rows if sample.get("review_status") != "reviewed"
        ),
        "reviewed_count": sum(
            1 for sample in sample_rows if sample.get("review_status") == "reviewed"
        ),
        "routing_summary": {
            "ready_family_count": sum(
                _int(item.get("ready_family_count")) for item in correction_lanes
            ),
            "boundary_family_count": sum(
                _int(item.get("boundary_family_count")) for item in correction_lanes
            ),
            "rejected_family_count": sum(
                _int(item.get("rejected_family_count")) for item in correction_lanes
            ),
            "pending_family_count": sum(
                _int(item.get("pending_family_count")) for item in correction_lanes
            ),
        },
        "correction_lanes": correction_lanes,
        "families": families,
    }


def _quality_provider_proposals_payload(con: sqlite3.Connection) -> dict[str, Any]:
    required_tables = {
        "ml_quality_provider_proposal_runs",
        "ml_quality_provider_proposals",
        "ml_quality_provider_proposal_cases",
    }
    if not all(_table_exists(con, table_name) for table_name in required_tables):
        return {"instrumented": False, "proposals": []}
    run = _one(
        con,
        """
        SELECT id AS run_id, run_key, rule_version, quality_epoch_id,
               discovery_run_id, score_run_id, actionable_family_count,
               proposal_count, positive_case_count, negative_case_count,
               boundary_case_count, status, summary_json, finished_at, updated_at
        FROM ml_quality_provider_proposal_runs
        WHERE status = 'completed'
        ORDER BY id DESC
        LIMIT 1
        """,
    )
    run_id = _int(run.get("run_id"))
    if not run_id:
        return {"instrumented": True, "proposals": []}
    run.pop("summary_json", None)
    proposals = _all(
        con,
        """
        SELECT proposal.id, proposal.proposal_key, proposal.provider_id,
               proposal.evidence_type, proposal.label, proposal.issue_type,
               proposal.token_context, proposal.status, proposal.priority,
               proposal.confidence, proposal.family_count, proposal.segment_count,
               proposal.manifest_draft_json, proposal.contract_json,
               SUM(CASE WHEN item.case_kind = 'positive' THEN 1 ELSE 0 END) AS positive_case_count,
               SUM(CASE WHEN item.case_kind = 'negative' THEN 1 ELSE 0 END) AS negative_case_count,
               SUM(CASE WHEN item.case_kind = 'boundary' THEN 1 ELSE 0 END) AS boundary_case_count
        FROM ml_quality_provider_proposals proposal
        LEFT JOIN ml_quality_provider_proposal_cases item ON item.proposal_id = proposal.id
        WHERE proposal.run_id = ?
        GROUP BY proposal.id
        ORDER BY proposal.priority DESC, proposal.id
        LIMIT 80
        """,
        (run_id,),
    )
    proposal_review_lookup = _regenerative_review_lookup(con, "proposal")
    for proposal in proposals:
        proposal_id = _int(proposal.get("id"))
        try:
            manifest = json.loads(proposal.get("manifest_draft_json") or "{}")
        except (TypeError, json.JSONDecodeError):
            manifest = {}
        proposal["manifest_draft"] = manifest if isinstance(manifest, dict) else {}
        proposal.pop("manifest_draft_json", None)
        try:
            contract = json.loads(proposal.get("contract_json") or "{}")
        except (TypeError, json.JSONDecodeError):
            contract = {}
        proposal["contract"] = contract if isinstance(contract, dict) else {}
        proposal["correction_lane"] = (
            proposal["contract"].get("correction_lane")
            if isinstance(proposal["contract"].get("correction_lane"), dict)
            else {"id": "other_patterns", "label": "Outros padrões confirmados"}
        )
        proposal["human_review"] = (
            proposal["contract"].get("human_evidence")
            if isinstance(proposal["contract"].get("human_evidence"), dict)
            else {}
        )
        proposal.pop("contract_json", None)
        cases = _all(
            con,
            """
            SELECT item.id AS case_id, item.case_key, item.case_kind,
                   item.segment_id, item.relative_path, item.source_key,
                   item.input_text, item.expected_behavior, item.assertions_json,
                   source.english_text, source.spanish_text, source.old_text,
                   output.portuguese_text AS output_text
            FROM ml_quality_provider_proposal_cases item
            LEFT JOIN source_segments source ON source.id = item.segment_id
            LEFT JOIN output_segments output ON output.segment_id = item.segment_id
            WHERE item.proposal_id = ?
            ORDER BY CASE item.case_kind
                       WHEN 'positive' THEN 0
                       WHEN 'boundary' THEN 1
                       ELSE 2
                     END,
                     item.id
            LIMIT 6
            """,
            (proposal_id,),
        )
        for item in cases:
            try:
                assertions = json.loads(item.get("assertions_json") or "[]")
            except (TypeError, json.JSONDecodeError):
                assertions = []
            item["assertions"] = assertions if isinstance(assertions, list) else []
            item.pop("assertions_json", None)
            case_key = str(item.get("case_key") or item.get("case_id") or "case")
            item_key = f"proposal:{proposal.get('proposal_key')}:case:{case_key}"
            evidence = {
                "proposal_key": str(proposal.get("proposal_key") or ""),
                "case_key": case_key,
                "case_kind": str(item.get("case_kind") or ""),
                "segment_id": _int(item.get("segment_id")),
                "input_hash": hashlib.sha256(
                    str(item.get("input_text") or "").encode("utf-8")
                ).hexdigest(),
                "expected_behavior_hash": hashlib.sha256(
                    str(item.get("expected_behavior") or "").encode("utf-8")
                ).hexdigest(),
                "assertions": item["assertions"],
                "provider_id": str(proposal.get("provider_id") or ""),
                "evidence_type": str(proposal.get("evidence_type") or ""),
            }
            _attach_regenerative_review_contract(
                item,
                queue_type="proposal",
                item_key=item_key,
                snapshot_id=run_id,
                evidence=evidence,
                decisions_by_evidence=proposal_review_lookup,
            )
        proposal["sample_cases"] = cases
    case_rows = [
        case
        for proposal in proposals
        for case in proposal.get("sample_cases") or []
        if isinstance(case, dict)
    ]
    return {
        "instrumented": True,
        **run,
        "draft_count": sum(
            1 for item in proposals if item.get("status") == "draft_review_required"
        ),
        "review_pending_count": sum(
            1 for case in case_rows if case.get("review_status") != "reviewed"
        ),
        "reviewed_count": sum(
            1 for case in case_rows if case.get("review_status") == "reviewed"
        ),
        "proposals": proposals,
    }


def _quality_closed_observation_audit_payload(con: sqlite3.Connection) -> dict[str, Any]:
    required_tables = {
        "ml_quality_closed_observation_audit_runs",
        "ml_quality_closed_observation_audit_items",
    }
    if not all(_table_exists(con, table_name) for table_name in required_tables):
        return {"instrumented": False, "review_samples": []}
    run = _one(
        con,
        """
        SELECT id AS run_id, run_key, rule_version, discovery_run_id,
               quality_epoch_id, score_run_id, segment_state_run_id,
               observation_count, closed_observation_count,
               sampled_family_count, sampled_segment_count, sampled_item_count, accepted_count,
               baseline_watch_count, review_required_count, inconsistent_count,
               duplicate_count, orphan_count, invalid_sample_count,
               status, summary_json, finished_at, updated_at
        FROM ml_quality_closed_observation_audit_runs
        WHERE status = 'completed'
        ORDER BY id DESC
        LIMIT 1
        """,
    )
    run_id = _int(run.get("run_id"))
    if not run_id:
        return {"instrumented": True, "review_samples": []}
    run.pop("summary_json", None)
    samples = _all(
        con,
        """
        SELECT family_id, segment_id, relative_path, source_key, evidence_kind,
               issue_type, token_context, file_family, text_relation, score,
               state_group, final_state, locked, confirmed_matches_output,
               needs_output_apply, confirmation_level, confirmation_source,
               confirmation_label, closure_class, review_reason, evidence_json
        FROM ml_quality_closed_observation_audit_items
        WHERE run_id = ?
          AND closure_class IN ('review_required', 'inconsistent_closure')
        ORDER BY CASE closure_class
                   WHEN 'inconsistent_closure' THEN 0
                   ELSE 1
                 END,
                 score IS NULL, score, family_id, segment_id
        LIMIT 40
        """,
        (run_id,),
    )
    for sample in samples:
        try:
            evidence = json.loads(sample.get("evidence_json") or "{}")
        except (TypeError, json.JSONDecodeError):
            evidence = {}
        sample["evidence"] = evidence if isinstance(evidence, dict) else {}
        sample.pop("evidence_json", None)
    return {"instrumented": True, **run, "review_samples": samples}


def _load_quality_promotion_provider_manifests(
    directory: Path = QUALITY_PROMOTION_PROVIDERS_DIR,
) -> list[dict[str, Any]]:
    providers: list[dict[str, Any]] = []
    for manifest_path in sorted(directory.glob("*.json")):
        try:
            payload = json.loads(manifest_path.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError):
            continue
        if not isinstance(payload, dict) or not payload.get("enabled", True):
            continue
        provider_id = str(payload.get("provider_id") or "").strip()
        evidence_type = str(payload.get("evidence_type") or "").strip()
        shadow_script = str(payload.get("shadow_script") or "").strip()
        if not provider_id or not evidence_type or not shadow_script:
            continue
        providers.append(
            {
                "provider_id": provider_id,
                "label": str(payload.get("label") or provider_id),
                "priority": _int(payload.get("priority"), 1000),
                "evidence_type": evidence_type,
                "shadow_script": shadow_script,
                "manifest_path": str(manifest_path),
            }
        )
    return sorted(providers, key=lambda item: (item["priority"], item["provider_id"]))


def _quality_promotion_provider_health_payload(
    con: sqlite3.Connection,
    quality_pattern_discovery: dict[str, Any],
    quality_epoch: dict[str, Any],
    *,
    provider_manifests: list[dict[str, Any]] | None = None,
) -> dict[str, Any]:
    providers = (
        _load_quality_promotion_provider_manifests()
        if provider_manifests is None
        else provider_manifests
    )
    score_run_id = (
        _int(quality_epoch.get("output_score_run_id"))
        or _int(quality_pattern_discovery.get("score_run_id"))
    )
    discovery_run_id = _int(quality_pattern_discovery.get("run_id"))
    family_metrics: dict[str, dict[str, int]] = {}
    uncovered_actionable_family_count = 0
    uncovered_actionable_reach = 0
    monitoring_family_count = 0
    closed_family_count = 0
    if discovery_run_id and all(
        _table_exists(con, table_name)
        for table_name in ("ml_quality_pattern_observations", "ml_quality_pattern_families")
    ):
        family_rows = _all(
            con,
            """
            SELECT family.provider_id, observation.status,
                   observation.segment_count, observation.metrics_json
            FROM ml_quality_pattern_observations observation
            JOIN ml_quality_pattern_families family ON family.id = observation.family_id
            WHERE observation.run_id = ?
            """,
            (discovery_run_id,),
        )
        for row in family_rows:
            status = str(row.get("status") or "")
            try:
                details = json.loads(row.get("metrics_json") or "{}")
            except (TypeError, json.JSONDecodeError):
                details = {}
            operational_reach = _int(
                details.get("operational_segment_count")
                if isinstance(details, dict)
                else 0
            )
            provider_id = str(row.get("provider_id") or "")
            if provider_id:
                metrics = family_metrics.setdefault(
                    provider_id,
                    {
                        "observed_family_count": 0,
                        "active_family_count": 0,
                        "closed_family_count": 0,
                        "operational_family_reach": 0,
                    },
                )
                metrics["observed_family_count"] += 1
                metrics["operational_family_reach"] += operational_reach
                if status == "closed_observation":
                    metrics["closed_family_count"] += 1
                elif status == "covered_by_provider":
                    metrics["active_family_count"] += 1
            if status in {"new_candidate", "recurring_candidate"}:
                uncovered_actionable_family_count += 1
                uncovered_actionable_reach += operational_reach or _int(row.get("segment_count"))
            elif status == "monitoring":
                monitoring_family_count += 1
            elif status == "closed_observation":
                closed_family_count += 1

    has_shadow = _table_exists(con, "ml_quality_shadow_runs")
    has_pairwise_runs = _table_exists(con, "ml_pairwise_quality_runs")
    has_active_evidence = all(
        _table_exists(con, table_name)
        for table_name in (
            "ml_pairwise_quality_evidence",
            "ml_pairwise_quality_runs",
            "output_segments",
        )
    )
    rows: list[dict[str, Any]] = []
    for manifest in providers:
        provider_id = str(manifest.get("provider_id") or "")
        evidence_type = str(manifest.get("evidence_type") or "")
        historical_run = (
            _one(
                con,
                """
                SELECT id, source_rule_version, source_score_run_id,
                       candidate_count, promotion_eligible_count, finished_at
                FROM ml_pairwise_quality_runs
                WHERE evidence_type = ?
                ORDER BY id DESC
                LIMIT 1
                """,
                (evidence_type,),
            )
            if has_pairwise_runs
            else {}
        )
        source_rule_version = str(historical_run.get("source_rule_version") or "")
        shadow_stem = Path(str(manifest.get("shadow_script") or "")).stem
        shadow = {}
        if has_shadow and score_run_id:
            if source_rule_version:
                shadow = _one(
                    con,
                    """
                    SELECT id, source_rule_version, score_run_id, record_count,
                           eligible_count, status, finished_at
                    FROM ml_quality_shadow_runs
                    WHERE score_run_id = ? AND source_rule_version = ?
                    ORDER BY id DESC LIMIT 1
                    """,
                    (score_run_id, source_rule_version),
                )
            if not shadow and shadow_stem:
                shadow = _one(
                    con,
                    """
                    SELECT id, source_rule_version, score_run_id, record_count,
                           eligible_count, status, finished_at
                    FROM ml_quality_shadow_runs
                    WHERE score_run_id = ? AND source_rule_version LIKE ?
                    ORDER BY id DESC LIMIT 1
                    """,
                    (score_run_id, f"{shadow_stem}_v%"),
                )
        current_evidence_run = (
            _one(
                con,
                """
                SELECT id, candidate_count, inserted_count, reused_count,
                       training_eligible_count, promotion_eligible_count, finished_at
                FROM ml_pairwise_quality_runs
                WHERE evidence_type = ? AND source_score_run_id = ?
                ORDER BY id DESC LIMIT 1
                """,
                (evidence_type, score_run_id),
            )
            if has_pairwise_runs and score_run_id
            else {}
        )
        promotion_ready_count = 0
        if has_active_evidence and score_run_id:
            promotion_ready_count = _int(
                _one(
                    con,
                    """
                    SELECT COUNT(DISTINCT evidence.segment_id) AS total
                    FROM ml_pairwise_quality_evidence evidence
                    JOIN ml_pairwise_quality_runs evidence_run ON evidence_run.id = evidence.last_run_id
                    JOIN output_segments output ON output.segment_id = evidence.segment_id
                    WHERE evidence.evidence_type = ?
                      AND evidence_run.source_score_run_id = ?
                      AND evidence.promotion_eligible = 1
                      AND evidence.id = (
                        SELECT MAX(latest.id)
                        FROM ml_pairwise_quality_evidence latest
                        WHERE latest.segment_id = evidence.segment_id
                          AND latest.evidence_type = evidence.evidence_type
                      )
                      AND output.portuguese_text = evidence.baseline_text
                      AND evidence.candidate_text <> output.portuguese_text
                    """,
                    (evidence_type, score_run_id),
                ).get("total")
            )
        last_productive = (
            _one(
                con,
                """
                SELECT id, source_score_run_id, candidate_count,
                       promotion_eligible_count, finished_at
                FROM ml_pairwise_quality_runs
                WHERE evidence_type = ? AND promotion_eligible_count > 0
                ORDER BY id DESC LIMIT 1
                """,
                (evidence_type,),
            )
            if has_pairwise_runs
            else {}
        )
        inspected_count = _int(shadow.get("record_count"))
        shadow_eligible_count = _int(shadow.get("eligible_count"))
        evidence_count = _int(current_evidence_run.get("candidate_count"))
        executed = bool(shadow and str(shadow.get("status") or "") == "completed")
        if not shadow:
            status = "not_run"
        elif str(shadow.get("status") or "") != "completed":
            status = "failed"
        elif promotion_ready_count > 0:
            status = "promotion_ready"
        elif shadow_eligible_count > 0 or evidence_count > 0:
            status = "candidates_filtered"
        else:
            status = "clean"
        owned = family_metrics.get(provider_id, {})
        rows.append(
            {
                "provider_id": provider_id,
                "label": manifest.get("label") or provider_id,
                "priority": _int(manifest.get("priority"), 1000),
                "evidence_type": evidence_type,
                "status": status,
                "executed": executed,
                "score_run_id": score_run_id or None,
                "shadow_run_id": _int(shadow.get("id")) or None,
                "shadow_rule_version": shadow.get("source_rule_version") or source_rule_version or None,
                "inspected_count": inspected_count,
                "shadow_eligible_count": shadow_eligible_count,
                "evidence_count": evidence_count,
                "promotion_ready_count": promotion_ready_count,
                "shadow_yield_rate": _pct(shadow_eligible_count, inspected_count),
                "promotion_yield_rate": _pct(promotion_ready_count, evidence_count),
                "observed_family_count": _int(owned.get("observed_family_count")),
                "active_family_count": _int(owned.get("active_family_count")),
                "closed_family_count": _int(owned.get("closed_family_count")),
                "operational_family_reach": _int(owned.get("operational_family_reach")),
                "finished_at": shadow.get("finished_at"),
                "last_productive_run_id": _int(last_productive.get("id")) or None,
                "last_productive_score_run_id": _int(last_productive.get("source_score_run_id")) or None,
                "last_productive_count": _int(last_productive.get("promotion_eligible_count")),
                "last_productive_at": last_productive.get("finished_at"),
            }
        )

    provider_count = len(rows)
    executed_provider_count = sum(1 for row in rows if row["executed"])
    healthy_provider_count = sum(
        1 for row in rows if row["status"] in {"clean", "promotion_ready", "candidates_filtered"}
    )
    productive_provider_count = sum(
        1
        for row in rows
        if row["shadow_eligible_count"] or row["evidence_count"] or row["promotion_ready_count"]
    )
    active_covered_family_count = sum(_int(row.get("active_family_count")) for row in rows)
    coverable_family_count = active_covered_family_count + uncovered_actionable_family_count
    coverage_rate = 100.0 if coverable_family_count == 0 else _pct(
        active_covered_family_count,
        coverable_family_count,
    )
    status = (
        "healthy"
        if provider_count and executed_provider_count == provider_count
        else "partial"
        if executed_provider_count
        else "not_instrumented"
    )
    return {
        "instrumented": bool(provider_count),
        "status": status,
        "quality_epoch_id": _int(quality_epoch.get("id")) or None,
        "score_run_id": score_run_id or None,
        "discovery_run_id": discovery_run_id or None,
        "provider_count": provider_count,
        "executed_provider_count": executed_provider_count,
        "healthy_provider_count": healthy_provider_count,
        "productive_provider_count": productive_provider_count,
        "inspected_count": sum(_int(row.get("inspected_count")) for row in rows),
        "shadow_eligible_count": sum(_int(row.get("shadow_eligible_count")) for row in rows),
        "evidence_count": sum(_int(row.get("evidence_count")) for row in rows),
        "promotion_ready_count": sum(_int(row.get("promotion_ready_count")) for row in rows),
        "active_covered_family_count": active_covered_family_count,
        "uncovered_actionable_family_count": uncovered_actionable_family_count,
        "uncovered_actionable_reach": uncovered_actionable_reach,
        "monitoring_family_count": monitoring_family_count,
        "closed_family_count": closed_family_count,
        "coverage_rate": coverage_rate,
        "providers": rows,
    }


def _operational_closure_payload(
    segment_state: dict[str, Any],
    output_coverage: float,
) -> dict[str, Any]:
    total = _int(segment_state.get("total_segments"))
    closed = _int(segment_state.get("closed_count"))
    pending = _int(segment_state.get("pending_count"))
    needs_apply = _int(segment_state.get("needs_apply"))
    blockers: list[str] = []
    if pending:
        blockers.append("pending_segments")
    if needs_apply:
        blockers.append("needs_output_apply")
    instrumented = bool(_int(segment_state.get("run_id")) and total)
    is_closed = bool(
        instrumented
        and closed >= total
        and pending == 0
        and needs_apply == 0
    )
    status = (
        "closed"
        if is_closed
        else "needs_apply"
        if needs_apply
        else "open"
        if instrumented
        else "unknown"
    )
    return {
        "instrumented": instrumented,
        "status": status,
        "is_closed": is_closed,
        "segment_state_run_id": _int(segment_state.get("run_id")) or None,
        "total_segments": total,
        "closed_count": closed,
        "closed_rate": _pct(closed, total),
        "pending_count": pending,
        "needs_apply": needs_apply,
        "output_coverage": output_coverage,
        "blocking_reasons": blockers,
        "definition": "segment_state_closed_without_pending_or_apply",
        "coverage_is_context_only": True,
    }


def _quality_debt_payload(
    quality_pattern_discovery: dict[str, Any],
    provider_health: dict[str, Any],
    diff_review: dict[str, Any],
    post_release_status: dict[str, Any],
) -> dict[str, Any]:
    diff_summary = diff_review.get("summary") if isinstance(diff_review.get("summary"), dict) else {}
    low_score = diff_review.get("low_score_cohorts") if isinstance(diff_review.get("low_score_cohorts"), dict) else {}
    feedback_summary = (
        post_release_status.get("summary")
        if isinstance(post_release_status.get("summary"), dict)
        else {}
    )
    calibration = (
        diff_review.get("calibration_review")
        if isinstance(diff_review.get("calibration_review"), dict)
        else {}
    )
    calibration_decision = str(calibration.get("policy_decision") or "not_evaluated")
    calibration_pending = (
        _int(calibration.get("pending_count"))
        if calibration_decision in {"sample", "required"}
        else 0
    )
    uncovered_families = _int(provider_health.get("uncovered_actionable_family_count"))
    uncovered_reach = _int(provider_health.get("uncovered_actionable_reach"))
    promotion_ready = _int(provider_health.get("promotion_ready_count"))
    effective_regressions = _int(
        diff_summary.get("effective_score_regressions"),
        _int(diff_summary.get("score_regressions")),
    )
    known_open = _int(
        feedback_summary.get("known_open_findings"),
        _int(feedback_summary.get("known_open")),
    )
    actionable_signal_count = (
        uncovered_families
        + promotion_ready
        + effective_regressions
        + known_open
        + calibration_pending
    )
    monitoring_families = _int(provider_health.get("monitoring_family_count"))
    discovery_complete = bool(
        quality_pattern_discovery.get("instrumented")
        and str(quality_pattern_discovery.get("status") or "") == "completed"
    )
    if actionable_signal_count:
        status = "actionable"
    elif discovery_complete and monitoring_families:
        status = "monitoring"
    elif discovery_complete and provider_health.get("status") == "healthy":
        status = "clear"
    else:
        status = "unknown"
    return {
        "instrumented": bool(discovery_complete and provider_health.get("instrumented")),
        "status": status,
        "has_actionable_debt": actionable_signal_count > 0,
        "actionable_signal_count": actionable_signal_count,
        "uncovered_actionable_family_count": uncovered_families,
        "uncovered_actionable_reach": uncovered_reach,
        "promotion_ready_count": promotion_ready,
        "effective_regression_count": effective_regressions,
        "known_open_finding_count": known_open,
        "calibration_pending_count": calibration_pending,
        "monitoring_family_count": monitoring_families,
        "closed_family_count": _int(provider_health.get("closed_family_count")),
        "risk_watch": {
            "actionable_low_score_count": _int(low_score.get("actionable")),
            "evidence_flagged_low_score_count": _int(low_score.get("evidence_flagged")),
            "lifecycle_closed_low_score_count": _int(low_score.get("lifecycle_closed")),
            "locked_low_score_count": _int(low_score.get("lifecycle_locked")),
            "informational_low_score_count": _int(low_score.get("informational")),
            "ignored_score_only_count": _int(quality_pattern_discovery.get("ignored_score_only_count")),
            "counted_as_quality_debt": False,
            "reason": "operational_score_is_baseline_sensitive_and_requires_specific_evidence",
        },
        "blocks_operational_closure": False,
        "definition": "specific_unresolved_quality_evidence_separate_from_operational_lifecycle",
    }


def _pending_taxonomy_summary_payload(
    con: sqlite3.Connection,
    run_id: int | None,
) -> dict[str, Any]:
    """Build only the operational taxonomy needed by the production dashboard."""
    if not run_id or not (
        _table_exists(con, "segment_state_runs")
        and _table_exists(con, "segment_state_items")
    ):
        return {
            "run_id": 0,
            "closed_consolidated": 0,
            "actionable_pending": 0,
            "actionable_pending_without_bridge": 0,
            "model_suspicion_watch": 0,
            "governed_bridge_pending": 0,
            "raw_pending": 0,
            "learning_backlog": 0,
            "needs_apply": 0,
            "select_cstring": {"total": 0, "closed": 0, "pending": 0},
            "distribution": [],
        }

    summary = _one(
        con,
        """
        SELECT
          closed_count,
          pending_count,
          output_apply_pending_count
        FROM segment_state_runs
        WHERE id = ?
        """,
        (run_id,),
    )
    bridge_tables_ready = _table_exists(con, "ml_issue_select_cstring_governed_bridge_proposal_items")
    select_cstring = {"total": 0, "closed": 0, "pending": 0}
    bridge_membership_sql = "0"
    if bridge_tables_ready:
        select_cstring = _one(
            con,
            """
            SELECT
              COUNT(*) AS total,
              COALESCE(SUM(CASE
                WHEN s.final_state = 'closed_auto_confirmed_select_cstring_governed_bridge'
                THEN 1 ELSE 0 END), 0) AS closed,
              COALESCE(SUM(CASE WHEN s.state_group = 'pending' THEN 1 ELSE 0 END), 0) AS pending
            FROM ml_issue_select_cstring_governed_bridge_proposal_items p
            JOIN (
              SELECT MAX(run_id) AS run_id
              FROM ml_issue_select_cstring_governed_bridge_proposal_items
            ) latest ON latest.run_id = p.run_id
            JOIN segment_state_items s
              ON s.segment_id = p.segment_id
             AND s.run_id = ?
            """,
            (run_id,),
        )
        bridge_membership_sql = """
          EXISTS (
            SELECT 1
            FROM ml_issue_select_cstring_governed_bridge_proposal_items bridge_item
            WHERE bridge_item.run_id = (
              SELECT MAX(latest_bridge.run_id)
              FROM ml_issue_select_cstring_governed_bridge_proposal_items latest_bridge
            )
              AND bridge_item.segment_id = s.segment_id
          )
        """
    high_severity_issue_sql = "0"
    if _table_exists(con, "issues"):
        high_severity_issue_sql = """
          EXISTS (
            SELECT 1
            FROM issues issue
            WHERE issue.segment_id = s.segment_id
              AND lower(issue.severity) IN ('high', 'error', 'critical')
          )
        """

    state_counts = _one(
        con,
        f"""
        SELECT
          COALESCE(SUM(CASE
            WHEN s.final_state = 'reopen_auto_confirmed_autofix'
             AND s.confirmed_matches_output = 1
             AND s.output_state = 'output_present'
             AND NOT (s.state_group = 'pending' AND ({bridge_membership_sql}))
             AND NOT ({high_severity_issue_sql})
            THEN 1 ELSE 0 END), 0) AS model_watch,
          COALESCE(SUM(CASE
            WHEN s.state_group = 'pending'
             AND (
               s.needs_output_apply = 1
               OR s.output_state IN ('output_missing', 'confirmation_mismatch')
               OR s.final_state IN (
                 'pending_unknown_open',
                 'pending_output_missing_real',
                 'pending_blocked_structure',
                 'pending_human_review',
                 'reopen_auto_confirmed'
               )
               OR ({high_severity_issue_sql})
               OR ({bridge_membership_sql})
             )
            THEN 1 ELSE 0 END), 0) AS actionable_pending
        FROM segment_state_items s
        WHERE s.run_id = ?
        """,
        (run_id,),
    )

    closed = _int(summary.get("closed_count"))
    raw_pending = _int(summary.get("pending_count"))
    needs_apply = _int(summary.get("output_apply_pending_count"))
    governed_bridge_pending = _int(select_cstring.get("pending"))
    actionable_pending = _int(state_counts.get("actionable_pending"))
    model_watch = _int(state_counts.get("model_watch"))
    actionable_without_bridge = max(actionable_pending - governed_bridge_pending, 0)
    learning_backlog = max(raw_pending - actionable_pending, 0)
    distribution = [
        {"name": "Consolidado", "value": closed, "group": "closed_consolidated", "color": "#10b981"},
        {"name": "Pendencia acionavel", "value": actionable_without_bridge, "group": "actionable_pending", "color": "#f59e0b"},
        {"name": "Suspeita ML / Watch", "value": model_watch, "group": "model_suspicion_watch", "color": "#8b5cf6"},
        {"name": "Ponte governada pendente", "value": governed_bridge_pending, "group": "governed_bridge_pending", "color": "#38bdf8"},
    ]
    return {
        "run_id": run_id,
        "closed_consolidated": closed,
        "actionable_pending": actionable_pending,
        "actionable_pending_without_bridge": actionable_without_bridge,
        "model_suspicion_watch": model_watch,
        "governed_bridge_pending": governed_bridge_pending,
        "raw_pending": raw_pending,
        "learning_backlog": learning_backlog,
        "needs_apply": needs_apply,
        "select_cstring": {
            "total": _int(select_cstring.get("total")),
            "closed": _int(select_cstring.get("closed")),
            "pending": governed_bridge_pending,
        },
        "distribution": [row for row in distribution if row["value"] > 0],
    }


def _pending_actionability_payload(con: sqlite3.Connection, segment_state_run_id: int | None) -> dict[str, Any]:
    ledger_run_id = _latest_ledger_run_id(con, segment_state_run_id)
    current_state = (
        _one(
            con,
            """
            SELECT pending_count, output_apply_pending_count
            FROM segment_state_runs
            WHERE id = ? AND finished_at IS NOT NULL
            """,
            (segment_state_run_id,),
        )
        if segment_state_run_id and _table_exists(con, "segment_state_runs")
        else {}
    )
    if (
        segment_state_run_id
        and _int(current_state.get("pending_count")) == 0
        and _int(current_state.get("output_apply_pending_count")) == 0
    ):
        return {
            "status": "not_applicable",
            "ledger_run_id": ledger_run_id,
            "segment_state_run_id": segment_state_run_id,
            "instrumented_pending": 0,
            "needs_context": 0,
            "needs_domain": 0,
            "needs_new_microagent": 0,
            "text_repair": 0,
            "high_uncertainty": 0,
            "other_watch": 0,
        }
    empty = {
        "status": "pending_instrumentation",
        "ledger_run_id": ledger_run_id,
        "instrumented_pending": 0,
        "needs_context": "pending_instrumentation",
        "needs_domain": "pending_instrumentation",
        "needs_new_microagent": "pending_instrumentation",
        "text_repair": "pending_instrumentation",
        "high_uncertainty": "pending_instrumentation",
        "other_watch": "pending_instrumentation",
    }
    if not segment_state_run_id or not ledger_run_id:
        return empty
    if not (_table_exists(con, "segment_state_items") and _table_exists(con, "ml_issue_ledger_items")):
        return empty

    row = _one(
        con,
        """
        WITH pending_issues AS (
          SELECT
            segment_id,
            lower(COALESCE(issue_family, '')) AS issue_family,
            lower(COALESCE(issue_kind, '')) AS issue_kind,
            lower(COALESCE(issue_severity, '')) AS issue_severity,
            lower(COALESCE(agent_key, '')) AS agent_key,
            lower(COALESCE(proposed_action, '')) AS proposed_action
          FROM ml_issue_ledger_items
          WHERE run_id = ?
            AND state_group = 'pending'
            AND COALESCE(status, 'open') = 'open'
        ),
        per_segment AS (
          SELECT
            segment_id,
            MAX(CASE
              WHEN issue_family LIKE '%context%'
                OR issue_kind LIKE '%context%'
                OR proposed_action LIKE '%context%'
              THEN 1 ELSE 0 END) AS needs_context,
            MAX(CASE
              WHEN issue_family LIKE '%domain%'
                OR issue_kind LIKE '%domain%'
                OR agent_key LIKE '%religion%'
                OR agent_key LIKE '%culture%'
                OR agent_key LIKE '%title%'
                OR agent_key LIKE '%nickname%'
              THEN 1 ELSE 0 END) AS needs_domain,
            MAX(CASE
              WHEN issue_kind LIKE '%new_microagent%'
                OR proposed_action LIKE '%new_microagent%'
                OR proposed_action LIKE '%needs_new%'
              THEN 1 ELSE 0 END) AS needs_new_microagent,
            MAX(CASE
              WHEN issue_kind LIKE '%repair%'
                OR issue_kind LIKE '%residual%'
                OR issue_kind LIKE '%boundary%'
                OR issue_kind LIKE '%literal%'
                OR issue_kind LIKE '%fluency%'
                OR issue_family LIKE '%spanish_residual%'
              THEN 1 ELSE 0 END) AS text_repair,
            MAX(CASE
              WHEN issue_severity IN ('high', 'error', 'critical')
                OR issue_kind LIKE '%uncertain%'
                OR issue_kind LIKE '%conflict%'
                OR proposed_action LIKE '%human%'
              THEN 1 ELSE 0 END) AS high_uncertainty
          FROM pending_issues
          GROUP BY segment_id
        )
        SELECT
          COUNT(*) AS instrumented_pending,
          COALESCE(SUM(needs_context), 0) AS needs_context,
          COALESCE(SUM(needs_domain), 0) AS needs_domain,
          COALESCE(SUM(needs_new_microagent), 0) AS needs_new_microagent,
          COALESCE(SUM(text_repair), 0) AS text_repair,
          COALESCE(SUM(high_uncertainty), 0) AS high_uncertainty,
          COALESCE(SUM(CASE
            WHEN needs_context = 0
             AND needs_domain = 0
             AND needs_new_microagent = 0
             AND text_repair = 0
             AND high_uncertainty = 0
            THEN 1 ELSE 0 END), 0) AS other_watch
        FROM per_segment
        """,
        (ledger_run_id,),
    )
    if not row:
        return empty
    if _int(row.get("instrumented_pending")) == 0:
        return empty
    return {
        "status": "instrumented",
        "ledger_run_id": ledger_run_id,
        "instrumented_pending": _int(row.get("instrumented_pending")),
        "needs_context": _int(row.get("needs_context")),
        "needs_domain": _int(row.get("needs_domain")),
        "needs_new_microagent": _int(row.get("needs_new_microagent")),
        "text_repair": _int(row.get("text_repair")),
        "high_uncertainty": _int(row.get("high_uncertainty")),
        "other_watch": _int(row.get("other_watch")),
    }


def _pending_next_focus_payload(
    taxonomy: dict[str, Any],
    pending_by_family: list[dict[str, Any]],
    actionability: dict[str, Any],
    needs_apply: int,
) -> dict[str, Any]:
    if needs_apply > 0:
        return {
            "label": "needs_apply",
            "reason": "ha output aguardando aplicacao segura",
            "status": "acao pronta",
            "count": needs_apply,
        }
    actionable = _int(taxonomy.get("actionable_pending"))
    if actionable > 0:
        return {
            "label": "fila acionavel",
            "reason": "existe revisao/aplicacao operacional pronta",
            "status": "acao pronta",
            "count": actionable,
        }
    bridge = _int(taxonomy.get("governed_bridge_pending"))
    if bridge > 0:
        return {
            "label": "ponte governada",
            "reason": "ha lifecycle/bridge pendente de decisao",
            "status": "aguardando politica",
            "count": bridge,
        }
    if pending_by_family:
        top = pending_by_family[0]
        return {
            "label": top.get("label") or "familia pendente",
            "reason": "maior volume pendente mapeado pelo ledger",
            "status": "amadurecer microagente/politica",
            "count": _int(top.get("value")),
        }
    if actionability.get("status") == "not_applicable":
        return {
            "label": "quality_debt_clear",
            "reason": "snapshot atual sem pendencias ou apply aguardando acao",
            "status": "nenhuma acao operacional",
            "count": 0,
        }
    instrumented = actionability.get("instrumented_pending")
    return {
        "label": "pending_instrumentation",
        "reason": "sem familia acionavel suficiente no payload atual",
        "status": "instrumentacao pendente",
        "count": _int(instrumented),
    }


def _source_update_readiness_payload(con: sqlite3.Connection) -> dict[str, Any]:
    required_tables = {
        "source_tree_snapshots",
        "source_tree_snapshot_files",
        "source_segments",
    }
    if not all(_table_exists(con, table_name) for table_name in required_tables):
        return {
            "instrumented": False,
            "status": "not_instrumented",
            "reason": "source_snapshot_tables_missing",
            "lanes": [],
        }
    snapshots = _all(
        con,
        """
        SELECT id, snapshot_label, game_version, english_tree_hash,
               spanish_tree_hash, english_file_count, spanish_file_count,
               english_total_bytes, spanish_total_bytes, metadata_json,
               created_at
        FROM source_tree_snapshots
        ORDER BY id DESC
        LIMIT 2
        """,
    )
    if not snapshots:
        return {
            "instrumented": True,
            "status": "awaiting_baseline_snapshot",
            "reason": "no_source_snapshot",
            "lanes": [],
        }
    current = dict(snapshots[0])
    previous = dict(snapshots[1]) if len(snapshots) > 1 else None
    for snapshot in (current, previous):
        if not snapshot:
            continue
        try:
            snapshot["metadata"] = json.loads(snapshot.pop("metadata_json") or "{}")
        except (TypeError, json.JSONDecodeError):
            snapshot["metadata"] = {}

    def snapshot_files(snapshot_id: int, source_kind: str) -> dict[str, dict[str, Any]]:
        return {
            str(row.get("relative_path") or ""): row
            for row in _all(
                con,
                """
                SELECT relative_path, file_hash, size_bytes, source_mtime_ns
                FROM source_tree_snapshot_files
                WHERE snapshot_id = ? AND source_kind = ?
                ORDER BY relative_path
                """,
                (snapshot_id, source_kind),
            )
            if row.get("relative_path")
        }

    def file_delta(source_kind: str) -> dict[str, Any]:
        current_files = snapshot_files(_int(current.get("id")), source_kind)
        previous_files = (
            snapshot_files(_int(previous.get("id")), source_kind)
            if previous
            else {}
        )
        current_paths = set(current_files)
        previous_paths = set(previous_files)
        new_paths = sorted(current_paths - previous_paths) if previous else []
        removed_paths = sorted(previous_paths - current_paths) if previous else []
        changed_paths = sorted(
            path
            for path in current_paths & previous_paths
            if current_files[path].get("file_hash")
            != previous_files[path].get("file_hash")
        ) if previous else []
        preserved_paths = sorted(
            path
            for path in current_paths & previous_paths
            if current_files[path].get("file_hash")
            == previous_files[path].get("file_hash")
        ) if previous else sorted(current_paths)
        return {
            "source_kind": source_kind,
            "new_count": len(new_paths),
            "changed_count": len(changed_paths),
            "removed_count": len(removed_paths),
            "preserved_count": len(preserved_paths),
            "new_paths": new_paths,
            "changed_paths": changed_paths,
            "removed_paths": removed_paths,
            "sample_paths": {
                "new": new_paths[:8],
                "changed": changed_paths[:8],
                "removed": removed_paths[:8],
            },
        }

    english_delta = file_delta("english")
    spanish_delta = file_delta("spanish")

    def segment_count(paths: list[str], active: int | None = None) -> int:
        if not paths:
            return 0
        placeholders = ", ".join("?" for _ in paths)
        active_sql = "" if active is None else " AND is_active = ?"
        params: tuple[Any, ...] = (*paths, *(() if active is None else (active,)))
        row = _one(
            con,
            f"""
            SELECT COUNT(*) AS total
            FROM source_segments
            WHERE relative_path IN ({placeholders}){active_sql}
            """,
            params,
        )
        return _int(row.get("total"))

    active_total = _int(
        _one(
            con,
            "SELECT COUNT(*) AS total FROM source_segments WHERE is_active = 1",
        ).get("total")
    )
    new_segments = segment_count(spanish_delta["new_paths"], active=1)
    changed_segments = segment_count(spanish_delta["changed_paths"], active=1)
    removed_segments = segment_count(spanish_delta["removed_paths"], active=0)
    preserved_segments = max(active_total - new_segments - changed_segments, 0)
    file_change_count = sum(
        _int(delta.get(key))
        for delta in (english_delta, spanish_delta)
        for key in ("new_count", "changed_count", "removed_count")
    )
    has_previous = previous is not None
    has_delta = has_previous and file_change_count > 0
    current_snapshot_id = _int(current.get("id"))
    adopted_epoch = (
        _one(
            con,
            """
            SELECT id, status, source_snapshot_id, segment_state_run_id,
                   evaluated_at, published_at, updated_at
            FROM quality_epochs
            WHERE source_snapshot_id = ?
            ORDER BY id DESC
            LIMIT 1
            """,
            (current_snapshot_id,),
        )
        if current_snapshot_id and _table_exists(con, "quality_epochs")
        else {}
    )
    snapshot_evaluated = bool(
        adopted_epoch
        and str(adopted_epoch.get("status") or "") in {"evaluated", "published"}
    )
    pending_source_evaluation = bool(has_delta and not snapshot_evaluated)
    status = (
        "change_pending_evaluation"
        if pending_source_evaluation
        else "change_evaluated"
        if has_delta
        else "source_stable"
        if has_previous
        else "baseline_ready"
    )
    lanes = [
        {
            "id": "new",
            "label": "Novos",
            "segment_count": new_segments,
            "file_count": _int(spanish_delta.get("new_count")),
            "action": "translate_from_zero",
            "description": "Entram sem herdar decisão textual; podem reutilizar apenas conhecimento e contratos compatíveis.",
        },
        {
            "id": "changed",
            "label": "Alterados",
            "segment_count": changed_segments,
            "file_count": _int(spanish_delta.get("changed_count")),
            "action": "revalidate_and_retranslate",
            "description": "Preservam o histórico, mas score, evidências e tradução precisam ser revalidados contra o novo source.",
        },
        {
            "id": "removed",
            "label": "Removidos",
            "segment_count": removed_segments,
            "file_count": _int(spanish_delta.get("removed_count")),
            "action": "archive_without_output",
            "description": "Saem do pacote ativo e permanecem apenas no histórico para auditoria e possível retorno futuro.",
        },
        {
            "id": "preserved",
            "label": "Preservados",
            "segment_count": preserved_segments,
            "file_count": _int(spanish_delta.get("preserved_count")),
            "action": "inherit_validated_state",
            "description": "Herdam tradução, decisões e score ativo quando hashes e contratos continuam compatíveis.",
        },
    ]
    return {
        "instrumented": True,
        "status": status,
        "has_previous_snapshot": has_previous,
        "has_delta": has_delta,
        "can_prepare_incremental_cycle": has_delta,
        "requires_full_evaluation": pending_source_evaluation,
        "pending_source_evaluation": pending_source_evaluation,
        "current_snapshot_evaluated": snapshot_evaluated,
        "adopted_quality_epoch": adopted_epoch,
        "current_snapshot": current,
        "previous_snapshot": previous,
        "file_delta": {
            "total_changed": file_change_count,
            "english": english_delta,
            "spanish": spanish_delta,
        },
        "segment_delta": {
            "contract": "file_exact_segment_affected_v1",
            "new": new_segments,
            "changed": changed_segments,
            "removed": removed_segments,
            "preserved": preserved_segments,
            "active_total": active_total,
            "note": "Arquivos são comparados por hash exato; segmentos alterados representam o conjunto afetado nos arquivos espanhóis modificados.",
        },
        "lanes": lanes,
        "gates": {
            "snapshot_frozen": True,
            "raw_score_preserved": True,
            "human_history_preserved": True,
            "output_write_allowed": False,
            "full_evaluation_required_before_publish": pending_source_evaluation,
        },
    }


def _build_app_state_payload(db_path: Path) -> dict[str, Any]:
    con = sqlite3.connect(db_path)
    con.row_factory = sqlite3.Row
    try:
        segment_state = _latest_segment_state_summary(con)
        post_release_status = _post_release_feedback_payload(segment_state)
        safety_status = _safe_full_production_payload(post_release_status, segment_state)
        learning = _learning_status_payload(con)
        run = _read_production_run_status()
        production_delta = _last_production_delta_payload(con, run, segment_state)
        segment_trend = _segment_state_trend(con)
        previous_state = segment_trend[-2] if len(segment_trend) > 1 else {}
        taxonomy = _pending_taxonomy_summary_payload(con, segment_state["run_id"])
        diff_review = _release_diff_review_payload(con, segment_state["run_id"])
        _apply_pairwise_calibration_gate(safety_status, diff_review)
        quality_pattern_discovery = _quality_pattern_discovery_payload(con)
        quality_provider_proposals = _quality_provider_proposals_payload(con)
        quality_closed_observation_audit = _quality_closed_observation_audit_payload(con)
        source_update_readiness = _source_update_readiness_payload(con)
        quality_epoch = (
            _one(
                con,
                """
                SELECT id, epoch_key, scoring_contract_hash, data_snapshot_hash,
                       source_snapshot_id, baseline_tree_hash, output_tree_hash,
                       model_run_id, model_version, scoring_rule_version,
                       old_score_run_id, output_score_run_id, policy_run_id,
                       segment_state_run_id, status, invalidation_reason,
                       created_at, scored_at, evaluated_at, published_at,
                       invalidated_at, updated_at
                FROM quality_epochs
                ORDER BY id DESC
                LIMIT 1
                """,
            )
            if _table_exists(con, "quality_epochs")
            else {}
        )
        epoch_status = str(quality_epoch.get("status") or "missing")
        active_model = (
            _one(
                con,
                """
                SELECT active_model_run_id, active_model_version
                FROM ml_model_registry
                WHERE model_kind = 'risk_action_classifier'
                LIMIT 1
                """,
            )
            if _table_exists(con, "ml_model_registry")
            else {}
        )
        active_model_run_id = _int(active_model.get("active_model_run_id"))
        epoch_model_is_active = bool(
            active_model_run_id
            and active_model_run_id == _int(quality_epoch.get("model_run_id"))
        )
        quality_epoch["active_model_run_id"] = active_model_run_id or None
        quality_epoch["active_model_version"] = active_model.get("active_model_version")
        quality_epoch["model_is_active"] = epoch_model_is_active
        score_preparation_required = _evaluation_requires_score_preparation(quality_epoch)
        if score_preparation_required:
            evaluation_gate = safety_status.setdefault("evaluation_gate", {})
            evaluation_gate["preparation_required"] = True
            evaluation_gate["blocking_reasons"] = [
                reason for reason in evaluation_gate.get("blocking_reasons", [])
                if reason != "quality_epoch_not_scored"
            ]
            if not evaluation_gate["blocking_reasons"]:
                evaluation_gate["status"] = "liberada"
                evaluation_gate["can_start_evaluation_full_production_now"] = True
        if not _quality_epoch_has_scores(epoch_status) and not score_preparation_required:
            evaluation_gate = safety_status.setdefault("evaluation_gate", {})
            evaluation_gate["status"] = "bloqueada"
            evaluation_gate["can_start_evaluation_full_production_now"] = False
            reasons = evaluation_gate.setdefault("blocking_reasons", [])
            if "quality_epoch_not_scored" not in reasons:
                reasons.append("quality_epoch_not_scored")
        if quality_epoch and active_model_run_id and not epoch_model_is_active:
            evaluation_gate = safety_status.setdefault("evaluation_gate", {})
            evaluation_gate["status"] = "bloqueada"
            evaluation_gate["can_start_evaluation_full_production_now"] = False
            evaluation_reasons = evaluation_gate.setdefault("blocking_reasons", [])
            if "quality_epoch_model_not_active" not in evaluation_reasons:
                evaluation_reasons.append("quality_epoch_model_not_active")
            publication_gate = safety_status.setdefault("publication_gate", {})
            publication_gate["status"] = "bloqueada"
            publication_gate["can_publish_after_full_production"] = False
            publication_gate["can_publish_after_full_production_now"] = False
            publication_reasons = publication_gate.setdefault("blocking_reasons", [])
            if "quality_epoch_model_not_active" not in publication_reasons:
                publication_reasons.append("quality_epoch_model_not_active")
        if segment_state["needs_apply"] and not _quality_epoch_has_evaluation(epoch_status):
            publication_gate = safety_status.setdefault("publication_gate", {})
            publication_gate["status"] = "bloqueada"
            publication_gate["can_publish_after_full_production"] = False
            reasons = publication_gate.setdefault("blocking_reasons", [])
            if "quality_epoch_not_evaluated" not in reasons:
                reasons.append("quality_epoch_not_evaluated")
        evaluation_decision = _read_json_file(EVALUATION_DECISION_LATEST_FILE)
        if evaluation_decision:
            evaluation_decision["stale"] = (
                _int(evaluation_decision.get("segment_state_run_id")) != _int(segment_state.get("run_id"))
            )
        pending_by_family = _pending_by_family_payload(con, segment_state["run_id"])
        package_versions = _package_versions_payload(con)
        quality_hotspots = _quality_hotspots_payload(con)
        pending_actionability = _pending_actionability_payload(con, segment_state["run_id"])
        output_coverage = _output_coverage(con)
        promotion_provider_health = _quality_promotion_provider_health_payload(
            con,
            quality_pattern_discovery,
            quality_epoch,
        )
        operational_closure = _operational_closure_payload(segment_state, output_coverage)
        quality_debt = _quality_debt_payload(
            quality_pattern_discovery,
            promotion_provider_health,
            diff_review,
            post_release_status,
        )
        pending_next_focus = _pending_next_focus_payload(
            taxonomy,
            pending_by_family,
            pending_actionability,
            segment_state["needs_apply"],
        )
        run_active = run.get("status") in {"starting", "running"}
        stages = run.get("stages") if run.get("run_id") else _new_production_run_status("preview").get("stages", [])
        stages = stages if isinstance(stages, list) else []
        progress_pct = _production_run_progress(run, stages)
        generated_at = datetime.now().isoformat(timespec="seconds")
        disk_preflight = _production_disk_preflight_payload()
        release_status = (
            "needs_apply"
            if segment_state["needs_apply"]
            else "ready_with_known_issues"
            if segment_state["pending_count"]
            else "ready_for_release"
        )
        return {
            "generated_at": generated_at,
            "cache": {
                "generated_at": generated_at,
                "source_db_mtime": _db_mtime(db_path),
                "stale": False,
            },
            "release": {
                "readiness": release_status,
                "total_segments": segment_state["total_segments"],
                "closed_count": segment_state["closed_count"],
                "pending_count": segment_state["pending_count"],
                "closed_rate": segment_state["closed_rate"],
                "needs_apply": segment_state["needs_apply"],
                "output_coverage": output_coverage,
                "operational_closure": operational_closure,
                "quality_debt": quality_debt,
                "promotion_provider_health": promotion_provider_health,
                "provider_proposals": quality_provider_proposals,
                "closed_observation_audit": quality_closed_observation_audit,
                "source_update_readiness": source_update_readiness,
                "latest_segment_state_run_id": segment_state["run_id"],
                "latest_ledger_run_id": _latest_ledger_run_id(con, segment_state["run_id"]),
                "quality_epoch": quality_epoch,
                "segment_state_finished_at": segment_state["finished_at"],
                "segment_state_trend": segment_trend,
                "previous_segment_state_delta": {
                    "available": bool(previous_state),
                    "baseline_segment_state_run_id": _int(previous_state.get("run_id")),
                    "closed_delta": segment_state["closed_count"] - _int(previous_state.get("closed_count")),
                    "pending_delta": segment_state["pending_count"] - _int(previous_state.get("pending_count")),
                    "needs_apply_delta": segment_state["needs_apply"] - _int(previous_state.get("needs_apply")),
                } if previous_state else {"available": False, "reason": "pending_instrumentation"},
                "since_last_production": production_delta,
                "qualified_pending": {
                    "actionable_pending": _int(taxonomy.get("actionable_pending")),
                    "context_domain": taxonomy.get("context_domain", "pending_instrumentation"),
                    "policy_waiting": _int(taxonomy.get("governed_bridge_pending")),
                    "high_uncertainty": _int(taxonomy.get("model_suspicion_watch")),
                    "raw_pending": _int(taxonomy.get("raw_pending")),
                },
                "pending_by_family": pending_by_family,
                "package_versions": package_versions,
                "quality_hotspots": quality_hotspots,
                "pending_actionability": pending_actionability,
                "pending_next_focus": pending_next_focus,
                "post_release": {
                    **post_release_status,
                    **post_release_status.get("summary", {}),
                    **safety_status.get("post_release_summary", {}),
                    "diff_review": diff_review,
                    "quality_pattern_discovery": quality_pattern_discovery,
                    "evaluation_decision": evaluation_decision,
                    "stable_baseline_path": post_release_status.get("baseline_control", {}).get("stable_baseline_path"),
                    "broken_release_path": post_release_status.get("baseline_control", {}).get("broken_release_path"),
                    "current_candidate_path": post_release_status.get("release_candidate", {}).get("current_candidate_path"),
                    "summary": {
                        **post_release_status.get("summary", {}),
                        **safety_status.get("post_release_summary", {}),
                        "known_open": post_release_status.get("summary", {}).get("known_open_findings"),
                        "closed": post_release_status.get("summary", {}).get("closed_findings"),
                        "parser_dynamic_backlog": post_release_status.get("summary", {}).get("parser_dynamic_backlog"),
                    },
                    "feedback_items": post_release_status.get("items", []),
                    "active_feedback_items": post_release_status.get("active_items", []),
                    "archived_feedback_items": post_release_status.get("archived_items", []),
                },
                "safety": safety_status,
                "evaluation_gate": safety_status.get("evaluation_gate", {}),
                "publication_gate": safety_status.get("publication_gate", {}),
                "baseline_control": {
                    **post_release_status.get("baseline_control", {}),
                    **safety_status.get("baseline_control", {}),
                },
                "visual_locks": {
                    **post_release_status.get("visual_locks", {}),
                    **safety_status.get("visual_locks", {}),
                },
                "release_candidate": {
                    **post_release_status.get("release_candidate", {}),
                    **safety_status.get("release_candidate", {}),
                },
                "source_output_update": {
                    **post_release_status.get("source_output_update", {}),
                    **safety_status.get("source_output_update", {}),
                    "readiness": source_update_readiness,
                },
                "disk_preflight": disk_preflight,
                "operational_integrity": {
                    "source_status": "pending_instrumentation",
                    "output_status": "pending_instrumentation",
                    "confirmations_status": "aligned" if segment_state["needs_apply"] == 0 else "attention",
                    "needs_apply_status": "ok" if segment_state["needs_apply"] == 0 else "attention",
                    "learning_gate_status": "released" if bool(learning.get("can_start_production")) else "blocked",
                },
            },
            "learning_gate": {
                "can_start_production": bool(learning.get("can_start_production")),
                "production_safe": bool(learning.get("production_safe")),
                "status": learning.get("status"),
                "reason": learning.get("reason") or learning.get("gate_message"),
                "current_phase_label": learning.get("current_phase_label"),
                "progress_pct": learning.get("progress_pct"),
                "lock": learning.get("lock") or {},
                "next_action": learning.get("next_action"),
            },
            "production": {
                "active": bool(run_active),
                "last_run": run or {},
                "current_stage": run.get("current_stage"),
                "progress_pct": progress_pct,
                "stages_compact": _cache_stage_compact(stages),
                "summary": {},
                "readiness": {},
                "disk_preflight": disk_preflight,
            },
            "navigation": {
                "dashboard_url": "http://127.0.0.1:5173/#Dashboard",
                "network_url": "http://127.0.0.1:5173/#Dashboard/Network",
            },
        }
    finally:
        con.close()


def _refresh_dashboard_cache(db_path: Path) -> dict[str, Any]:
    global DASHBOARD_CACHE
    payload = _build_app_state_payload(db_path)
    cache_payload = {
        "schema_version": DASHBOARD_CACHE_SCHEMA_VERSION,
        "generated_at": datetime.now().isoformat(timespec="seconds"),
        "source_db_mtime": _db_mtime(db_path),
        "source_low_score_segmented_shadow_run_id": (
            _latest_low_score_segmented_shadow_run_id(db_path)
        ),
        "source_dynamic_score_holdout_id": _latest_dynamic_score_holdout_id(db_path),
        "source_glossary_display_case_policy_signature": (
            _glossary_display_case_policy_signature(db_path)
        ),
        "source_mojibake_lexicon_review_signature": (
            _mojibake_lexicon_review_signature(db_path)
        ),
        "app_state": payload,
    }
    cache_file = _dashboard_cache_file()
    cache_file.parent.mkdir(parents=True, exist_ok=True)
    cache_file.write_text(json.dumps(cache_payload, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    DASHBOARD_CACHE = cache_payload
    return cache_payload


def _get_dashboard_cache(db_path: Path, *, force: bool = False) -> dict[str, Any]:
    global DASHBOARD_CACHE
    with DASHBOARD_CACHE_LOCK:
        current_shadow_run_id = _latest_low_score_segmented_shadow_run_id(db_path)
        current_dynamic_holdout_id = _latest_dynamic_score_holdout_id(db_path)
        current_glossary_policy_signature = (
            _glossary_display_case_policy_signature(db_path)
        )
        current_mojibake_review_signature = (
            _mojibake_lexicon_review_signature(db_path)
        )

        def cache_is_current(candidate: dict[str, Any]) -> bool:
            if int(candidate.get("schema_version") or 0) != DASHBOARD_CACHE_SCHEMA_VERSION:
                return False
            cached_shadow_run_id = candidate.get(
                "source_low_score_segmented_shadow_run_id"
            )
            shadow_is_current = (
                current_shadow_run_id is None
                or _int(cached_shadow_run_id) == current_shadow_run_id
            )
            dynamic_holdout_is_current = (
                current_dynamic_holdout_id is None
                or _int(candidate.get("source_dynamic_score_holdout_id"))
                == current_dynamic_holdout_id
            )
            glossary_policy_is_current = (
                current_glossary_policy_signature is None
                or candidate.get(
                    "source_glossary_display_case_policy_signature"
                )
                == current_glossary_policy_signature
            )
            mojibake_review_is_current = (
                current_mojibake_review_signature is None
                or candidate.get(
                    "source_mojibake_lexicon_review_signature"
                )
                == current_mojibake_review_signature
            )
            return (
                shadow_is_current
                and dynamic_holdout_is_current
                and glossary_policy_is_current
                and mojibake_review_is_current
            )

        if (
            not force
            and DASHBOARD_CACHE is not None
            and cache_is_current(DASHBOARD_CACHE)
        ):
            return DASHBOARD_CACHE
        cache_file = _dashboard_cache_file()
        if not force and cache_file.exists():
            try:
                candidate = json.loads(cache_file.read_text(encoding="utf-8"))
                if cache_is_current(candidate):
                    DASHBOARD_CACHE = candidate
                    return DASHBOARD_CACHE
            except json.JSONDecodeError:
                DASHBOARD_CACHE = None
        return _refresh_dashboard_cache(db_path)


DIAGNOSTIC_PHASE_BLUEPRINT = (
    ("state", "Estado atual"),
    ("discovery", "Descoberta"),
    ("suggestions", "Sugestões"),
    ("consolidation", "Consolidação"),
)

DIAGNOSTIC_STAGE_METADATA = {
    "source_update_sync": ("state", "Verificar e sincronizar arquivos de origem"),
    "quality_epoch_open": ("state", "Abrir ou reutilizar epoch"),
    "score_package_old": ("state", "Pontuar baseline"),
    "score_package_output": ("state", "Pontuar output"),
    "score_package_policy": ("state", "Calibrar política de score"),
    "quality_epoch_finalize": ("state", "Fixar scores da epoch"),
    "quality_epoch_contract": ("state", "Validar contrato da epoch"),
    "supervised_learning_apply": ("state", "Consolidar decisões humanas no aprendizado"),
    "segment_state": ("state", "Recalcular segment-state"),
    "offline_correction_candidates": ("suggestions", "Gerar novas correções determinísticas"),
    "quality_promotion_discovery": ("discovery", "Descobrir e registrar sugestões"),
    "quality_epoch_noop_close": ("consolidation", "Fechar epoch sem alterações"),
    "dashboard_cache": ("consolidation", "Consolidar cache e painel"),
}


def _diagnostic_status_progress(status: dict[str, Any]) -> int:
    if status.get("status") == "completed":
        return 100
    stages = status.get("stages") or []
    if not stages:
        return 1
    planned_stage_count = max(
        len(stages),
        _int(status.get("planned_stage_count")) or len(stages),
    )
    completed = sum(1 for stage in stages if stage.get("status") == "done")
    running_fraction = max(
        (
            min(99.0, max(0.0, float(stage.get("progress_pct") or 0))) / 100.0
            for stage in stages
            if stage.get("status") == "running"
        ),
        default=0.0,
    )
    return max(
        1,
        min(99, round(((completed + running_fraction) / planned_stage_count) * 100)),
    )


def _write_diagnostic_status(status: dict[str, Any]) -> None:
    status["updated_at"] = _now_iso()
    status["progress_pct"] = _diagnostic_status_progress(status)
    DIAGNOSTIC_RUN_STATUS_FILE.parent.mkdir(parents=True, exist_ok=True)
    with DIAGNOSTIC_STATUS_LOCK:
        DIAGNOSTIC_RUN_STATUS_FILE.write_text(
            json.dumps(status, ensure_ascii=False, indent=2) + "\n",
            encoding="utf-8",
        )


def _read_diagnostic_status() -> dict[str, Any]:
    with DIAGNOSTIC_STATUS_LOCK:
        if not DIAGNOSTIC_RUN_STATUS_FILE.exists():
            return {}
        try:
            payload = json.loads(DIAGNOSTIC_RUN_STATUS_FILE.read_text(encoding="utf-8-sig"))
        except (OSError, json.JSONDecodeError):
            return {}
    return payload if isinstance(payload, dict) else {}


def _new_diagnostic_status() -> dict[str, Any]:
    started_at = _now_iso()
    status = {
        "run_id": datetime.now().strftime("%Y%m%d_%H%M%S_%f"),
        "status": "running",
        "started_at": started_at,
        "updated_at": started_at,
        "finished_at": "",
        "current_stage": "",
        "current_label": "Preparar diagnóstico",
        "progress_pct": 1,
        "planned_stage_count": 9,
        "phases": [
            {"id": phase_id, "label": label, "status": "pending"}
            for phase_id, label in DIAGNOSTIC_PHASE_BLUEPRINT
        ],
        "stages": [],
        "error": "",
    }
    _write_diagnostic_status(status)
    return status


def _diagnostic_start_stage(status: dict[str, Any], stage_id: str) -> None:
    phase_id, label = DIAGNOSTIC_STAGE_METADATA.get(
        stage_id,
        ("state", stage_id.replace("_", " ").title()),
    )
    phase_ids = [phase[0] for phase in DIAGNOSTIC_PHASE_BLUEPRINT]
    phase_index = phase_ids.index(phase_id)
    for index, phase in enumerate(status.get("phases") or []):
        if index < phase_index and phase.get("status") == "pending":
            phase["status"] = "done"
        if phase.get("id") == phase_id:
            phase["status"] = "running"
            phase["current_stage"] = stage_id
            phase["current_label"] = label
    status["status"] = "running"
    status["current_stage"] = stage_id
    status["current_label"] = label
    status.setdefault("stages", []).append(
        {
            "id": stage_id,
            "label": label,
            "phase": phase_id,
            "status": "running",
            "started_at": _now_iso(),
            "updated_at": _now_iso(),
            "heartbeat_at": "",
            "elapsed_seconds": 0,
            "progress_pct": 1,
            "finished_at": "",
            "exit_code": None,
        }
    )
    _write_diagnostic_status(status)


def _diagnostic_finish_stage(
    status: dict[str, Any],
    stage_id: str,
    *,
    exit_code: int,
    stdout_tail: list[str] | None = None,
    stderr_tail: list[str] | None = None,
) -> None:
    stage = next(
        (item for item in reversed(status.get("stages") or []) if item.get("id") == stage_id),
        None,
    )
    if stage is not None:
        stage["status"] = "done" if exit_code == 0 else "failed"
        stage["updated_at"] = _now_iso()
        stage["finished_at"] = stage["updated_at"]
        stage["exit_code"] = exit_code
        if exit_code == 0:
            stage["progress_pct"] = 100
        stage["stdout_tail"] = list(stdout_tail or [])[-12:]
        stage["stderr_tail"] = list(stderr_tail or [])[-12:]

    phase_id, _ = DIAGNOSTIC_STAGE_METADATA.get(stage_id, ("state", stage_id))
    phase = next(
        (item for item in status.get("phases") or [] if item.get("id") == phase_id),
        None,
    )
    if exit_code != 0:
        if phase is not None:
            phase["status"] = "failed"
        status["status"] = "failed"
        status["finished_at"] = _now_iso()
        status["error"] = "\n".join((stderr_tail or stdout_tail or [])[-12:])
    elif stage_id == "segment_state":
        if phase is not None:
            phase["status"] = "done"
    elif stage_id == "quality_promotion_discovery":
        if phase is not None:
            phase["status"] = "done"
        suggestions = next(
            (item for item in status.get("phases") or [] if item.get("id") == "suggestions"),
            None,
        )
        if suggestions is not None:
            suggestions["status"] = "done"
            suggestions["current_stage"] = stage_id
            suggestions["current_label"] = "Registrar sugestões de melhoria"
    elif stage_id == "dashboard_cache":
        if phase is not None:
            phase["status"] = "done"
        status["status"] = "completed"
        status["finished_at"] = _now_iso()
        status["current_label"] = "Diagnóstico concluído"
    _write_diagnostic_status(status)


DIAGNOSTIC_STAGE_EXPECTED_SECONDS = {
    "source_tree_snapshot": 30,
    "quality_epoch_open": 15,
    "score_package_old": 300,
    "score_package_output": 300,
    "score_package_policy": 60,
    "quality_epoch_finalize": 30,
    "supervised_learning_apply": 60,
    "segment_state": 600,
    "offline_correction_candidates": 300,
    "quality_promotion_discovery": 120,
    "quality_epoch_noop_close": 30,
}


def _diagnostic_stage_progress(stage_id: str, elapsed_seconds: float) -> int:
    expected_seconds = max(1, DIAGNOSTIC_STAGE_EXPECTED_SECONDS.get(stage_id, 120))
    return min(95, max(2, round((elapsed_seconds / expected_seconds) * 90)))


def _run_diagnostic_command(
    status: dict[str, Any],
    stage_id: str,
    command: list[str],
    *,
    timeout: int,
    heartbeat_interval: float = 5.0,
) -> subprocess.CompletedProcess[str]:
    command = _normalize_pipeline_command(command)
    env = os.environ.copy()
    env["PYTHONUNBUFFERED"] = "1"
    process = subprocess.Popen(
        command,
        cwd=str(ROOT),
        env=env,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
        encoding="utf-8",
        errors="replace",
    )
    started_monotonic = time.monotonic()
    heartbeat_stop = threading.Event()

    def heartbeat_status() -> None:
        while not heartbeat_stop.wait(heartbeat_interval):
            if process.poll() is not None:
                break
            elapsed_seconds = time.monotonic() - started_monotonic
            now = _now_iso()
            stage = next(
                (item for item in reversed(status.get("stages") or []) if item.get("id") == stage_id),
                None,
            )
            if stage is None:
                break
            stage.update(
                {
                    "updated_at": now,
                    "heartbeat_at": now,
                    "elapsed_seconds": round(elapsed_seconds, 1),
                    "progress_pct": _diagnostic_stage_progress(stage_id, elapsed_seconds),
                }
            )
            status["heartbeat_at"] = now
            _write_diagnostic_status(status)

    heartbeat_thread = threading.Thread(target=heartbeat_status, daemon=True)
    heartbeat_thread.start()
    timed_out = False
    try:
        stdout, stderr = process.communicate(timeout=timeout)
    except subprocess.TimeoutExpired:
        timed_out = True
        process.kill()
        stdout, stderr = process.communicate()
    finally:
        heartbeat_stop.set()
        heartbeat_thread.join(timeout=1.0)

    if timed_out:
        timeout_message = f"Command timed out after {timeout} seconds."
        stderr = f"{stderr.rstrip()}\n{timeout_message}" if stderr else timeout_message
    return subprocess.CompletedProcess(
        command,
        124 if timed_out else process.returncode,
        stdout,
        stderr,
    )


def _diagnostic_score_sources(epoch_payload: dict[str, Any]) -> list[str]:
    score_plan = epoch_payload.get("score_plan")
    if not isinstance(score_plan, dict):
        return ["old", "output"]
    required_sources = score_plan.get("required_sources")
    if not isinstance(required_sources, list):
        return ["old", "output"]
    sources: list[str] = []
    for source in required_sources:
        normalized = str(source or "").strip().lower()
        if normalized in {"old", "output"} and normalized not in sources:
            sources.append(normalized)
    return sources or ["old", "output"]


def _resumable_diagnostic_score_run_id(
    db_path: Path,
    epoch_payload: dict[str, Any],
    score_source: str,
) -> int | None:
    fingerprint = epoch_payload.get("fingerprint") or {}
    tree_hash_key = "baseline_tree_hash" if score_source == "old" else "output_tree_hash"
    with sqlite3.connect(db_path) as con:
        con.row_factory = sqlite3.Row
        row = con.execute(
            """
            SELECT id
            FROM ml_score_runs
            WHERE finished_at IS NULL
              AND model_run_id = ?
              AND source_snapshot_id = ?
              AND candidate_text_source = ?
              AND candidate_tree_hash = ?
              AND path_filter IS NULL
              AND limit_count IS NULL
              AND scored_count > 0
            ORDER BY id DESC
            LIMIT 1
            """,
            (
                _int(fingerprint.get("model_run_id")),
                _int(fingerprint.get("source_snapshot_id")),
                score_source,
                fingerprint.get(tree_hash_key),
            ),
        ).fetchone()
    return _int(row["id"]) or None if row else None


def _resumable_diagnostic_segment_state_run_id(
    db_path: Path,
    epoch_payload: dict[str, Any],
    *,
    include_attached: bool = False,
) -> int | None:
    """Find a complete, compatible state snapshot for this epoch.

    Fresh scoring must advance beyond the state already attached to the epoch.
    When the epoch itself is reused without scoring, the attached snapshot is
    still authoritative and may be reused to avoid an identical full rebuild.
    """
    epoch_id = _int(epoch_payload.get("epoch_id"))
    if not epoch_id:
        return None
    con: sqlite3.Connection | None = None
    try:
        con = sqlite3.connect(db_path)
        con.row_factory = sqlite3.Row
        attached_operator = ">=" if include_attached else ">"
        row = con.execute(
            f"""
            SELECT state.id
            FROM quality_epochs AS epoch
            JOIN segment_state_runs AS state
              ON state.finished_at IS NOT NULL
             AND state.total_segments > 1000
             AND state.total_segments = COALESCE(state.closed_count, 0) + COALESCE(state.pending_count, 0)
             AND state.id {attached_operator} COALESCE(epoch.segment_state_run_id, 0)
             AND state.candidate_score_run_id = epoch.output_score_run_id
             AND (
                   state.policy_run_id = epoch.policy_run_id
                   OR (state.policy_run_id IS NULL AND epoch.policy_run_id IS NULL)
             )
             AND (epoch.scored_at IS NULL OR state.started_at >= epoch.scored_at)
            LEFT JOIN segment_state_runs AS attached
              ON attached.id = epoch.segment_state_run_id
            WHERE epoch.id = ?
              AND (attached.rule_version IS NULL OR state.rule_version = attached.rule_version)
              AND EXISTS (
                  SELECT 1
                  FROM segment_state_items AS item
                  WHERE item.run_id = state.id
                  LIMIT 1
              )
            ORDER BY state.finished_at DESC, state.id DESC
            LIMIT 1
            """,
            (epoch_id,),
        ).fetchone()
    except sqlite3.Error:
        return None
    finally:
        if con is not None:
            con.close()
    return (_int(row["id"]) or None) if row else None


def _diagnostic_stage_timeout(stage_id: str) -> int:
    if stage_id.startswith("score_package_"):
        return 7200
    if stage_id in {"segment_state", "offline_correction_candidates"}:
        return 1800
    return 900


def _run_diagnostic_segment_state(db_path: Path) -> dict[str, Any]:
    started_at = _now_iso()
    diagnostic_status = _new_diagnostic_status()
    previous_run_id = 0
    try:
        with sqlite3.connect(db_path) as con:
            con.row_factory = sqlite3.Row
            previous_run_id = _latest_segment_state_summary(con).get("run_id") or 0
    except Exception:
        previous_run_id = 0

    epoch_bootstrap_commands = [
        (
            "source_update_sync",
            [sys.executable, "pipeline/source_update_sync.py", "--label", "diagnostic_quality_epoch"],
        ),
        (
            "quality_epoch_open",
            [sys.executable, "pipeline/quality_epoch.py", "open", "--source", "diagnostic"],
        ),
    ]
    scoring_commands: list[tuple[str, list[str]]] = []
    analysis_commands = [
        (
            "supervised_learning_apply",
            [sys.executable, "pipeline/main.py", "learn-feedback"],
        ),
        (
            "segment_state",
            [sys.executable, "pipeline/main.py", "segment-state"],
        ),
        (
            "offline_correction_candidates",
            [sys.executable, "pipeline/offline_residual_proposals.py", "--limit", "5000"],
        ),
        (
            "quality_promotion_discovery",
            [sys.executable, "pipeline/quality_promotion_cycle.py", "diagnostic"],
        ),
        (
            "quality_epoch_noop_close",
            [sys.executable, "pipeline/quality_epoch.py", "close-noop", "--source", "diagnostic"],
        ),
    ]
    command_results: list[dict[str, Any]] = []
    process_returncode = 0
    epoch_payload: dict[str, Any] = {}
    needs_scoring = True
    score_sources: list[str] = []
    commands = list(epoch_bootstrap_commands)
    for stage_id, command in commands:
        _diagnostic_start_stage(diagnostic_status, stage_id)
        process = _run_diagnostic_command(
            diagnostic_status,
            stage_id,
            command,
            timeout=_diagnostic_stage_timeout(stage_id),
        )
        stdout_lines = (process.stdout or "").splitlines()
        stderr_lines = (process.stderr or "").splitlines()
        command_results.append(
            {
                "stage_id": stage_id,
                "command": command,
                "exit_code": process.returncode,
                "stdout_tail": stdout_lines[-12:],
                "stderr_tail": stderr_lines[-12:],
            }
        )
        _diagnostic_finish_stage(
            diagnostic_status,
            stage_id,
            exit_code=process.returncode,
            stdout_tail=stdout_lines,
            stderr_tail=stderr_lines,
        )
        if process.returncode != 0:
            process_returncode = process.returncode
            break
        if stage_id == "quality_epoch_open":
            for line in reversed(stdout_lines):
                if not line.startswith("[quality_epoch] "):
                    continue
                try:
                    epoch_payload = json.loads(line.split("[quality_epoch] ", 1)[1])
                except json.JSONDecodeError:
                    epoch_payload = {}
                break
            needs_scoring = epoch_payload.get("needs_scoring") is not False
            if not needs_scoring:
                diagnostic_status["planned_stage_count"] = (
                    len(epoch_bootstrap_commands) + len(analysis_commands) + 1
                )
                _write_diagnostic_status(diagnostic_status)

    if process_returncode == 0 and needs_scoring:
        model_run_id = _int((epoch_payload.get("fingerprint") or {}).get("model_run_id"))
        if not model_run_id:
            process_returncode = 1
            _diagnostic_start_stage(diagnostic_status, "quality_epoch_contract")
            command_results.append(
                {
                    "stage_id": "quality_epoch_contract",
                    "command": [],
                    "exit_code": 1,
                    "stdout_tail": [],
                    "stderr_tail": ["Quality epoch did not provide a pinned model_run_id."],
                }
            )
            _diagnostic_finish_stage(
                diagnostic_status,
                "quality_epoch_contract",
                exit_code=1,
                stderr_tail=["Quality epoch did not provide a pinned model_run_id."],
            )
        else:
            score_base = [sys.executable, "pipeline/main.py", "ml-score", "--ml-model-run-id", str(model_run_id)]
            score_sources = _diagnostic_score_sources(epoch_payload)
            scoring_commands = []
            for score_source in score_sources:
                score_command = [
                    *score_base,
                    "--ml-candidate-text-source",
                    score_source,
                    "--ml-include-locked",
                ]
                resume_run_id = _resumable_diagnostic_score_run_id(
                    db_path,
                    epoch_payload,
                    score_source,
                )
                if resume_run_id:
                    score_command.extend(["--ml-resume-run-id", str(resume_run_id)])
                scoring_commands.append((f"score_package_{score_source}", score_command))
            scoring_commands += [
                ("score_package_policy", [sys.executable, "pipeline/main.py", "ml-group-threshold-policy"]),
                (
                    "quality_epoch_finalize",
                    [sys.executable, "pipeline/quality_epoch.py", "finalize-scoring", "--source", "diagnostic"],
                ),
            ]
            diagnostic_status["planned_stage_count"] = (
                len(epoch_bootstrap_commands)
                + len(scoring_commands)
                + len(analysis_commands)
                + 1
            )
            _write_diagnostic_status(diagnostic_status)

    if process_returncode == 0:
        remaining_commands = (scoring_commands if needs_scoring else []) + analysis_commands
        for stage_id, command in remaining_commands:
            _diagnostic_start_stage(diagnostic_status, stage_id)
            resumed_segment_state_run_id = 0
            segment_state_recovery = ""
            if stage_id == "segment_state":
                resumed_segment_state_run_id = (
                    _resumable_diagnostic_segment_state_run_id(
                        db_path,
                        epoch_payload,
                        include_attached=not needs_scoring,
                    )
                    or 0
                )
            if resumed_segment_state_run_id:
                segment_state_recovery = "compatible_committed_snapshot"
                process = subprocess.CompletedProcess(
                    command,
                    0,
                    (
                        "[diagnostic] Reusing committed segment-state run "
                        f"{resumed_segment_state_run_id}; auxiliary report state is ignored.\n"
                    ),
                    "",
                )
            else:
                process = _run_diagnostic_command(
                    diagnostic_status,
                    stage_id,
                    command,
                    timeout=_diagnostic_stage_timeout(stage_id),
                )
            stdout_lines = (process.stdout or "").splitlines()
            stderr_lines = (process.stderr or "").splitlines()
            stage_exit_code = process.returncode
            if stage_id == "segment_state" and stage_exit_code == 124:
                recovered_run_id = (
                    _resumable_diagnostic_segment_state_run_id(
                        db_path,
                        epoch_payload,
                        include_attached=not needs_scoring,
                    )
                    or 0
                )
                if recovered_run_id:
                    resumed_segment_state_run_id = recovered_run_id
                    segment_state_recovery = "critical_snapshot_committed_before_timeout"
                    stage_exit_code = 0
                    stdout_lines.append(
                        "[diagnostic] Segment-state core committed as run "
                        f"{recovered_run_id} before timeout; auxiliary work does not invalidate it."
                    )
                    stderr_lines = [
                        line
                        for line in stderr_lines
                        if not line.startswith("Command timed out after ")
                    ]
            if stage_id == "segment_state" and stage_exit_code == 0:
                epoch_id = _int(epoch_payload.get("epoch_id"))
                if not resumed_segment_state_run_id:
                    resumed_segment_state_run_id = (
                        _resumable_diagnostic_segment_state_run_id(
                            db_path,
                            epoch_payload,
                            include_attached=not needs_scoring,
                        )
                        or 0
                    )
                attach_command = [
                    sys.executable,
                    "pipeline/quality_epoch.py",
                    "attach-state",
                    "--source",
                    "diagnostic",
                ]
                if epoch_id:
                    attach_command.extend(["--epoch-id", str(epoch_id)])
                if resumed_segment_state_run_id:
                    attach_command.extend(
                        ["--segment-state-run-id", str(resumed_segment_state_run_id)]
                    )
                attach_process = subprocess.run(
                    _normalize_pipeline_command(attach_command),
                    cwd=str(ROOT),
                    capture_output=True,
                    text=True,
                    timeout=300,
                )
                stdout_lines.extend((attach_process.stdout or "").splitlines())
                stderr_lines.extend((attach_process.stderr or "").splitlines())
                if attach_process.returncode != 0:
                    stage_exit_code = attach_process.returncode
                else:
                    for line in reversed((attach_process.stdout or "").splitlines()):
                        if not line.startswith("[quality_epoch] "):
                            continue
                        try:
                            attach_payload = json.loads(line.split("[quality_epoch] ", 1)[1])
                        except json.JSONDecodeError:
                            attach_payload = {}
                        if attach_payload:
                            epoch_payload = {**epoch_payload, **attach_payload}
                        break
            if stage_id == "quality_epoch_noop_close" and stage_exit_code == 0:
                for line in reversed(stdout_lines):
                    if not line.startswith("[quality_epoch] "):
                        continue
                    try:
                        close_payload = json.loads(line.split("[quality_epoch] ", 1)[1])
                    except json.JSONDecodeError:
                        close_payload = {}
                    if close_payload:
                        epoch_payload = {**epoch_payload, **close_payload}
                    break
            command_results.append(
                {
                    "stage_id": stage_id,
                    "command": command,
                    "exit_code": stage_exit_code,
                    "resumed_segment_state_run_id": resumed_segment_state_run_id or None,
                    "segment_state_recovery": segment_state_recovery or None,
                    "stdout_tail": stdout_lines[-12:],
                    "stderr_tail": stderr_lines[-12:],
                }
            )
            _diagnostic_finish_stage(
                diagnostic_status,
                stage_id,
                exit_code=stage_exit_code,
                stdout_tail=stdout_lines,
                stderr_tail=stderr_lines,
            )
            if stage_exit_code != 0:
                process_returncode = stage_exit_code
                break

    new_run_id = 0
    try:
        with sqlite3.connect(db_path) as con:
            con.row_factory = sqlite3.Row
            new_run_id = _latest_segment_state_summary(con).get("run_id") or 0
    except Exception:
        new_run_id = 0

    last_result = command_results[-1] if command_results else {}
    return {
        "started_at": started_at,
        "finished_at": _now_iso(),
        "exit_code": process_returncode,
        "previous_segment_state_run_id": previous_run_id,
        "new_segment_state_run_id": new_run_id,
        "created_new_segment_state_run": bool(new_run_id and new_run_id != previous_run_id),
        "diagnostic_contract": "open_or_reuse_quality_epoch_score_consistently_and_suggest_without_confirming_or_writing_output",
        "quality_epoch": epoch_payload,
        "quality_epoch_scoring_performed": needs_scoring,
        "quality_epoch_score_sources": score_sources,
        "diagnostic_status": diagnostic_status,
        "stages": command_results,
        "stdout_tail": last_result.get("stdout_tail", []),
        "stderr_tail": last_result.get("stderr_tail", []),
    }


def _app_state_payload(db_path: Path, *, force: bool = False) -> dict[str, Any]:
    cache = _get_dashboard_cache(db_path, force=force)
    app_state = dict(cache.get("app_state") or {})
    app_state["cache"] = dict(app_state.get("cache") or {})
    app_state["cache"].update(
        {
            "generated_at": cache.get("generated_at"),
            "source_db_mtime": cache.get("source_db_mtime"),
            "stale": _db_mtime(db_path) != cache.get("source_db_mtime"),
        }
    )

    # O snapshot do dashboard pode permanecer em cache durante uma produção longa,
    # mas a run atual é pequena e persistida separadamente. Sobrepor somente esse
    # estado evita que o frontend volte a exibir uma run concluída/placeholder no
    # meio de Diagnóstico, Avaliação ou Publicação.
    historical_run = _read_production_run_status()
    if historical_run.get("run_id"):
        run, reconciliation = _production_run_for_current_state(app_state, historical_run)
        stages = run.get("stages")
        stages = stages if isinstance(stages, list) else []
        production = dict(app_state.get("production") or {})
        production.update(
            {
                "active": run.get("status") in {"starting", "running"},
                "last_run": run,
                "current_stage": run.get("current_stage"),
                "progress_pct": _production_run_progress(run, stages),
                "stages_compact": _cache_stage_compact(stages),
            }
        )
        if reconciliation:
            production["last_failed_run"] = historical_run
            production["run_reconciliation"] = reconciliation
        elif run.get("reconciled"):
            persisted_failure = run.get("last_failed_run")
            if isinstance(persisted_failure, dict) and persisted_failure.get("run_id"):
                production["last_failed_run"] = persisted_failure
            persisted_reconciliation = run.get("reconciliation")
            if isinstance(persisted_reconciliation, dict):
                production["run_reconciliation"] = persisted_reconciliation
        else:
            production.pop("run_reconciliation", None)
        app_state["production"] = production
    return app_state


def _latest_local_learning_run_id(db_path: Path) -> int:
    try:
        with sqlite3.connect(db_path) as con:
            con.row_factory = sqlite3.Row
            if _table_exists(con, "local_learning_candidates"):
                row = con.execute("SELECT MAX(run_id) AS run_id FROM local_learning_candidates").fetchone()
                if row is not None and row["run_id"] is not None:
                    return int(row["run_id"])
            if _table_exists(con, "local_learning_runs"):
                row = con.execute("SELECT MAX(id) AS run_id FROM local_learning_runs").fetchone()
                if row is not None and row["run_id"] is not None:
                    return int(row["run_id"])
    except Exception:
        pass
    return 0


def _publication_lifecycle_apply_readiness(
    db_path: Path,
    *,
    state_run_id: int | None,
    segment_ids: list[int],
) -> dict[str, Any]:
    if not segment_ids:
        return {
            "available": True,
            "state_run_id": state_run_id,
            "candidates": 0,
            "ready": 0,
            "blocked": 0,
            "result_counts": {},
        }
    pipeline_dir = ROOT / "pipeline"
    if str(pipeline_dir) not in sys.path:
        sys.path.insert(0, str(pipeline_dir))
    try:
        import general_pipe_article_gender_lifecycle_policy_materializer as bridge  # type: ignore
        import human_confirmed_local_learning_lifecycle_policy_materializer as materializer  # type: ignore
    except Exception as exc:
        return {
            "available": False,
            "state_run_id": state_run_id,
            "candidates": len(segment_ids),
            "ready": 0,
            "blocked": len(segment_ids),
            "result_counts": {"materializer_import_failed": len(segment_ids)},
            "error": str(exc),
        }

    previous_rule_version = getattr(bridge, "RULE_VERSION", None)
    previous_target_segment_ids = getattr(bridge, "TARGET_SEGMENT_IDS", ())
    previous_default_state_run_id = getattr(bridge, "DEFAULT_SEGMENT_STATE_RUN_ID", None)
    try:
        con = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True, timeout=60)
        con.row_factory = sqlite3.Row
        con.execute("PRAGMA query_only = ON")
        try:
            selected_state_run_id = _int(state_run_id) or _int(_latest_segment_state_summary(con).get("run_id"))
            # O segment-state intermediario existe apenas para confirmar a escrita
            # por segmento e nao materializa um novo issue-ledger. O proprio
            # materializador governa evidencias pelo ultimo ledger concluido;
            # a pre-validacao deve usar exatamente o mesmo contrato.
            ledger_run_id = bridge.latest_finished_ledger_run_id(con)
            if not selected_state_run_id or not ledger_run_id:
                return {
                    "available": False,
                    "state_run_id": selected_state_run_id,
                    "ledger_run_id": ledger_run_id,
                    "candidates": len(segment_ids),
                    "ready": 0,
                    "blocked": len(segment_ids),
                    "result_counts": {"missing_state_or_ledger": len(segment_ids)},
                }
            materializer.configure_bridge(tuple(segment_ids), selected_state_run_id)
            rows = bridge.collect_rows(con, selected_state_run_id, ledger_run_id)
        finally:
            con.close()
    except Exception as exc:
        return {
            "available": False,
            "state_run_id": state_run_id,
            "candidates": len(segment_ids),
            "ready": 0,
            "blocked": len(segment_ids),
            "result_counts": {"lifecycle_readiness_failed": len(segment_ids)},
            "error": str(exc),
        }
    finally:
        if previous_rule_version is not None:
            bridge.RULE_VERSION = previous_rule_version
        bridge.TARGET_SEGMENT_IDS = previous_target_segment_ids
        if previous_default_state_run_id is not None:
            bridge.DEFAULT_SEGMENT_STATE_RUN_ID = previous_default_state_run_id

    result_counts: dict[str, int] = {}
    ready = 0
    ready_ids: list[int] = []
    blocked_items: list[dict[str, Any]] = []
    for row in rows:
        if row.get("policy_allowed"):
            ready += 1
            ready_ids.append(_int(row.get("segment_id")))
            result_counts["ready"] = result_counts.get("ready", 0) + 1
        else:
            reason = str(row.get("block_reason") or "blocked")
            result_counts[reason] = result_counts.get(reason, 0) + 1
            blocked_items.append(
                {
                    "segment_id": _int(row.get("segment_id")),
                    "reason": reason,
                    "relative_path": row.get("relative_path"),
                    "source_key": row.get("source_key"),
                }
            )
    missing = max(0, len(segment_ids) - len(rows))
    if missing:
        result_counts["missing_from_materializer"] = result_counts.get("missing_from_materializer", 0) + missing
        returned_ids = {_int(row.get("segment_id")) for row in rows}
        blocked_items.extend(
            {"segment_id": segment_id, "reason": "missing_from_materializer", "relative_path": None, "source_key": None}
            for segment_id in segment_ids
            if segment_id not in returned_ids
        )
    return {
        "available": True,
        "state_run_id": state_run_id,
        "ledger_run_id": ledger_run_id,
        "candidates": len(segment_ids),
        "materializer_rows": len(rows),
        "ready": ready,
        "ready_ids": ready_ids,
        "blocked": max(0, len(segment_ids) - ready),
        "blocked_items": blocked_items,
        "result_counts": result_counts,
        "policy_name": getattr(bridge, "POLICY_NAME", "human_confirmed_post_apply_repair_lifecycle_bridge"),
        "policy_action": getattr(bridge, "POLICY_ACTION", "close_reopen_human_confirmed_post_apply_repair_lifecycle"),
    }


def _publication_preflight_payload(db_path: Path, *, force: bool = True) -> dict[str, Any]:
    app_state = _app_state_payload(db_path, force=force)
    release = app_state.get("release") or {}
    post_release = release.get("post_release") or {}
    diff_review = post_release.get("diff_review") or {}
    diff_summary = diff_review.get("summary") or {}
    safety = release.get("safety") or {}
    publication_gate = safety.get("publication_gate") or release.get("publication_gate") or {}
    active_feedback = post_release.get("active_feedback_items") or post_release.get("active_items") or []

    state_run_id = _int(release.get("latest_segment_state_run_id")) or None
    apply_records = diff_review.get("apply_segments") if isinstance(diff_review.get("apply_segments"), list) else []
    apply_preview_count = len(apply_records)
    apply_kind_counts: dict[str, int] = {}
    for record in apply_records:
        if not isinstance(record, dict):
            continue
        kind = str(record.get("apply_kind") or "unknown")
        apply_kind_counts[kind] = apply_kind_counts.get(kind, 0) + 1
    lifecycle_apply_count = _int(
        diff_summary.get("lifecycle_apply_count"),
        apply_kind_counts.get("lifecycle_closure", 0),
    )
    output_apply_count = _int(
        diff_summary.get("output_apply_count"),
        apply_kind_counts.get("output_write", 0),
    )
    apply_count = lifecycle_apply_count + output_apply_count
    apply_segment_ids = _publication_apply_segment_ids(
        {"app_state": app_state},
        db_path=db_path,
        state_run_id=state_run_id,
        output_apply_count=output_apply_count,
    )
    apply_population_count = len(apply_segment_ids)
    mixed_apply_kind = lifecycle_apply_count > 0 and output_apply_count > 0
    token_policy_run_id = _latest_apply_token_policy_run_id(db_path, state_run_id) if output_apply_count > 0 else None
    apply_readiness = (
        _publication_lifecycle_apply_readiness(
            db_path,
            state_run_id=state_run_id,
            segment_ids=apply_segment_ids,
        )
        if lifecycle_apply_count > 0 and output_apply_count == 0
        else _publication_apply_readiness(
            db_path,
            state_run_id=state_run_id,
            segment_ids=apply_segment_ids,
        )
        if output_apply_count > 0 and lifecycle_apply_count == 0
        else {
            "available": not mixed_apply_kind,
            "candidates": apply_count,
            "ready": 0,
            "blocked": apply_count,
            "result_counts": {"mixed_apply_kind_not_supported": apply_count} if mixed_apply_kind else {},
        }
    )
    apply_policy_readiness = (
        _publication_apply_readiness(
            db_path,
            state_run_id=state_run_id,
            segment_ids=apply_segment_ids,
            require_token_policy_decision=True,
            token_policy_run_id=token_policy_run_id,
        )
        if output_apply_count > 0 and lifecycle_apply_count == 0 and token_policy_run_id is not None
        else {
            "available": token_policy_run_id is not None or apply_count == 0 or lifecycle_apply_count > 0,
            "state_run_id": state_run_id,
            "require_token_policy_decision": True,
            "token_policy_run_id": token_policy_run_id,
            "candidates": 0,
            "ready": 0,
            "blocked": output_apply_count,
            "result_counts": {"missing_token_policy_run": output_apply_count} if output_apply_count > 0 else {},
        }
    )
    apply_mixed_readiness = (
        _publication_apply_readiness(
            db_path,
            state_run_id=state_run_id,
            segment_ids=apply_segment_ids,
            allow_token_policy_decision=True,
            token_policy_run_id=token_policy_run_id,
        )
        if output_apply_count > 0 and lifecycle_apply_count == 0 and token_policy_run_id is not None
        else {
            "available": token_policy_run_id is not None or apply_count == 0 or lifecycle_apply_count > 0,
            "state_run_id": state_run_id,
            "allow_token_policy_decision": True,
            "token_policy_run_id": token_policy_run_id,
            "candidates": 0,
            "ready": 0,
            "blocked": output_apply_count,
            "result_counts": {"missing_token_policy_run": output_apply_count} if output_apply_count > 0 else {},
        }
    )
    apply_ready_count = _int(apply_readiness.get("ready"))
    apply_blocked_count = _int(apply_readiness.get("blocked"))
    apply_result_counts = apply_readiness.get("result_counts") if isinstance(apply_readiness.get("result_counts"), dict) else {}
    apply_policy_ready_count = _int(apply_policy_readiness.get("ready"))
    apply_policy_blocked_count = _int(apply_policy_readiness.get("blocked"))
    apply_policy_result_counts = (
        apply_policy_readiness.get("result_counts")
        if isinstance(apply_policy_readiness.get("result_counts"), dict)
        else {}
    )
    apply_mixed_ready_count = _int(apply_mixed_readiness.get("ready"))
    apply_mixed_blocked_count = _int(apply_mixed_readiness.get("blocked"))
    apply_mixed_result_counts = (
        apply_mixed_readiness.get("result_counts")
        if isinstance(apply_mixed_readiness.get("result_counts"), dict)
        else {}
    )
    promotion_count = _int(diff_summary.get("promotions_vs_old"), len(diff_review.get("promotion_segments") or []))
    raw_regression_count = _int(diff_summary.get("score_regressions"))
    regression_count = _int(
        diff_summary.get("effective_package_score_regressions"),
        raw_regression_count,
    )
    unhandled_count = _int(diff_summary.get("unhandled_by_network"), _int(release.get("pending_count")))
    low_score_count = _int(diff_summary.get("low_score"))
    feedback_count = len(active_feedback) if isinstance(active_feedback, list) else _int(post_release.get("active_findings"))
    changed_quality = diff_summary.get("changed_score_comparison") if isinstance(diff_summary.get("changed_score_comparison"), dict) else {}
    package_quality = diff_summary.get("package_score_comparison") if isinstance(diff_summary.get("package_score_comparison"), dict) else {}
    promotion_quality = diff_summary.get("promotion_score_comparison") if isinstance(diff_summary.get("promotion_score_comparison"), dict) else {}
    new_quality = diff_summary.get("new_score_summary") if isinstance(diff_summary.get("new_score_summary"), dict) else {}
    package_old_score = package_quality.get("weighted_avg_old_score") or package_quality.get("avg_old_score")
    package_new_score = (
        package_quality.get("weighted_avg_new_score")
        or package_quality.get("avg_new_score")
        or package_quality.get("package_quality_score")
    )
    package_delta = package_quality.get("weighted_avg_delta") or package_quality.get("avg_delta")

    blocking_reasons: list[str] = []
    warning_reasons: list[str] = []

    if apply_count > 0:
        blocking_reasons.append("apply_queue_pending")
    if mixed_apply_kind:
        blocking_reasons.append("mixed_apply_kind_not_supported")
    for reason in publication_gate.get("blocking_reasons") or []:
        if reason not in blocking_reasons:
            blocking_reasons.append(str(reason))
    if feedback_count > 0:
        blocking_reasons.append("active_feedback")
    if regression_count > 0:
        warning_reasons.append("score_regressions_require_fallback_review")
    if unhandled_count > 0:
        warning_reasons.append("unhandled_segments_require_backlog")
    if low_score_count > 0:
        warning_reasons.append("low_score_segments_require_backlog")

    can_publish_now = not blocking_reasons and publication_gate.get("can_publish_after_full_production_now") is True
    can_apply_normal = (
        apply_count > 0
        and apply_population_count == apply_count
        and output_apply_count == apply_count
        and apply_ready_count == apply_count
    )
    can_apply_token_policy = (
        apply_count > 0
        and apply_population_count == apply_count
        and output_apply_count == apply_count
        and apply_policy_ready_count == apply_count
    )
    can_apply_mixed_token_policy = (
        apply_count > 0
        and apply_population_count == apply_count
        and output_apply_count == apply_count
        and apply_mixed_ready_count == apply_count
    )
    can_apply_lifecycle = (
        apply_count > 0
        and apply_population_count == apply_count
        and lifecycle_apply_count == apply_count
        and apply_ready_count == apply_count
    )
    can_apply_pending = can_apply_lifecycle or can_apply_normal or can_apply_token_policy or can_apply_mixed_token_policy
    apply_strategy = (
        "lifecycle_closure"
        if can_apply_lifecycle
        else "normal"
        if can_apply_normal
        else "token_policy"
        if can_apply_token_policy
        else "mixed_token_policy"
        if can_apply_mixed_token_policy
        else "blocked"
    )
    status = "ready" if can_publish_now else "blocked"
    lifecycle_apply_blocked = lifecycle_apply_count > 0 and apply_blocked_count > 0
    output_apply_blocked = output_apply_count > 0 and apply_blocked_count > 0
    next_action = (
        "publish_candidate"
        if can_publish_now
        else "apply_confirmed_queue"
        if can_apply_pending
        else "review_lifecycle_apply_queue"
        if lifecycle_apply_blocked
        else "review_token_mismatch_queue"
        if output_apply_blocked
        else "review_apply_queue"
        if apply_count > 0
        else "review_publication_blockers"
    )

    payload = {
        "generated_at": _now_iso(),
        "status": status,
        "can_publish_now": can_publish_now,
        "can_apply_pending": can_apply_pending,
        "apply_strategy": apply_strategy,
        "next_action": next_action,
        "segment_state_run_id": release.get("latest_segment_state_run_id"),
        "token_policy_run_id": token_policy_run_id,
        "score_run_id": diff_summary.get("score_run_id") or diff_review.get("score_run_id"),
        "old_score_run_id": diff_summary.get("old_score_run_id") or diff_review.get("old_score_run_id"),
        "counts": {
            "needs_apply": apply_count,
            "apply_preview": apply_preview_count,
            "apply_population": apply_population_count,
            "apply_lifecycle": lifecycle_apply_count,
            "apply_output_write": output_apply_count,
            "apply_kind_mixed": 1 if mixed_apply_kind else 0,
            "apply_ready": apply_ready_count,
            "apply_blocked": apply_blocked_count,
            "lifecycle_apply_ready": apply_ready_count if lifecycle_apply_count else 0,
            "lifecycle_apply_blocked": apply_blocked_count if lifecycle_apply_count else 0,
            "apply_token_mismatch": _int(apply_result_counts.get("token_mismatch")),
            "apply_missing_token_policy": _int(apply_result_counts.get("missing_token_policy_decision")),
            "apply_policy_ready": apply_policy_ready_count,
            "apply_policy_blocked": apply_policy_blocked_count,
            "apply_policy_token_mismatch": _int(apply_policy_result_counts.get("token_mismatch")),
            "apply_policy_missing_decision": _int(apply_policy_result_counts.get("missing_token_policy_decision")),
            "apply_policy_missing_run": _int(apply_policy_result_counts.get("missing_token_policy_run")),
            "apply_policy_stale_confirmed_hash": _int(apply_policy_result_counts.get("stale_token_policy_confirmed_hash")),
            "apply_policy_stale_output_hash": _int(apply_policy_result_counts.get("stale_token_policy_output_hash")),
            "apply_mixed_ready": apply_mixed_ready_count,
            "apply_mixed_blocked": apply_mixed_blocked_count,
            "apply_mixed_token_mismatch": _int(apply_mixed_result_counts.get("token_mismatch")),
            "apply_mixed_token_policy_ready": _int(apply_mixed_result_counts.get("ready_token_policy_decision")),
            "apply_mixed_missing_decision": _int(apply_mixed_result_counts.get("missing_token_policy_decision")),
            "apply_mixed_stale_confirmed_hash": _int(apply_mixed_result_counts.get("stale_token_policy_confirmed_hash")),
            "apply_mixed_stale_output_hash": _int(apply_mixed_result_counts.get("stale_token_policy_output_hash")),
            "apply_already_matches": _int(apply_result_counts.get("already_matches"))
            + _int(apply_result_counts.get("already_matches_line")),
            "package_diff": _int(diff_summary.get("package_diff_count")),
            "raw_output_diff": _int(diff_summary.get("raw_output_diff_count"), _int(diff_summary.get("changed_vs_old"))),
            "package_excluded": _int(diff_summary.get("package_excluded_count")),
            "promotions": promotion_count,
            "score_regressions": regression_count,
            "raw_score_regressions": raw_regression_count,
            "unhandled_by_network": unhandled_count,
            "low_score": low_score_count,
            "active_feedback": feedback_count,
        },
        "apply_readiness": apply_readiness,
        "apply_policy_readiness": apply_policy_readiness,
        "apply_mixed_readiness": apply_mixed_readiness,
        "quality": {
            "package_old_score": package_old_score,
            "package_new_score": package_new_score,
            "package_delta": package_delta,
            "package": package_quality,
            "changed": changed_quality,
            "promotions": promotion_quality,
            "new_segments": new_quality,
        },
        "blocking_reasons": blocking_reasons,
        "warning_reasons": warning_reasons,
        "publication_gate": publication_gate,
        "summary": {
            "apply_queue": (
                "ready_for_protected_apply"
                if can_apply_pending
                else "lifecycle_review_required"
                if lifecycle_apply_blocked
                else "token_policy_or_review_required"
                if output_apply_blocked
                else "needs_review"
                if apply_count > 0
                else "empty"
            ),
            "promotions": "available_for_review" if promotion_count > 0 else "empty",
            "regressions": "fallback_or_review_required" if regression_count > 0 else "clear",
            "publication": "ready" if can_publish_now else "blocked",
        },
    }
    return {"ok": True, "publication_preflight": payload, "app_state": app_state}


def _compact_publication_preflight_payload(payload: dict[str, Any]) -> dict[str, Any]:
    """Return only what the preflight UI consumes; app-state refresh is separate."""

    return {
        "ok": bool(payload.get("ok")),
        "publication_preflight": payload.get("publication_preflight") or {},
    }


def _publication_apply_segment_ids(
    preflight_payload: dict[str, Any],
    *,
    db_path: Path | None = None,
    state_run_id: int | None = None,
    output_apply_count: int | None = None,
) -> list[int]:
    app_state = preflight_payload.get("app_state") if isinstance(preflight_payload, dict) else {}
    release = app_state.get("release") if isinstance(app_state, dict) else {}
    post_release = release.get("post_release") if isinstance(release, dict) else {}
    diff_review = post_release.get("diff_review") if isinstance(post_release, dict) else {}
    segment_ids: list[int] = []
    for item in diff_review.get("apply_segments") or []:
        if not isinstance(item, dict):
            continue
        if db_path is not None and output_apply_count and item.get("apply_kind") == "output_write":
            continue
        segment_id = _int(item.get("segment_id"))
        if segment_id:
            segment_ids.append(segment_id)
    if db_path is not None and state_run_id and output_apply_count:
        try:
            con = sqlite3.connect(db_path)
            try:
                rows = con.execute(
                    """
                    SELECT state.segment_id
                    FROM segment_state_items state
                    JOIN source_segments source
                      ON source.id = state.segment_id
                     AND source.is_active = 1
                    WHERE state.run_id = ?
                      AND COALESCE(state.needs_output_apply, 0) = 1
                    ORDER BY
                      COALESCE(state.priority_score, 0) DESC,
                      state.relative_path,
                      state.source_line_number,
                      state.segment_id
                    """,
                    (state_run_id,),
                ).fetchall()
            finally:
                con.close()
            segment_ids.extend(int(row[0]) for row in rows)
        except sqlite3.Error:
            # Preserve the preview fallback; the population mismatch blocks apply.
            for item in diff_review.get("apply_segments") or []:
                if not isinstance(item, dict) or item.get("apply_kind") != "output_write":
                    continue
                segment_id = _int(item.get("segment_id"))
                if segment_id:
                    segment_ids.append(segment_id)
    return list(dict.fromkeys(segment_ids))


def _latest_apply_token_policy_run_id(db_path: Path, state_run_id: int | None) -> int | None:
    try:
        with sqlite3.connect(db_path) as con:
            con.row_factory = sqlite3.Row
            if not _table_exists(con, "segment_token_policy_runs"):
                return None
            params: tuple[Any, ...] = ()
            state_sql = ""
            if state_run_id:
                state_sql = "AND state_run_id = ?"
                params = (state_run_id,)
            row = con.execute(
                f"""
                SELECT id
                FROM segment_token_policy_runs
                WHERE finished_at IS NOT NULL
                  AND total_candidates > 0
                  {state_sql}
                ORDER BY finished_at DESC, id DESC
                LIMIT 1
                """,
                params,
            ).fetchone()
            if row is not None:
                return int(row["id"])
            if state_run_id:
                row = con.execute(
                    """
                    SELECT id
                    FROM segment_token_policy_runs
                    WHERE finished_at IS NOT NULL
                      AND total_candidates > 0
                    ORDER BY finished_at DESC, id DESC
                    LIMIT 1
                    """
                ).fetchone()
                if row is not None:
                    return int(row["id"])
    except Exception:
        return None
    return None


def _publication_apply_readiness(
    db_path: Path,
    *,
    state_run_id: int | None,
    segment_ids: list[int],
    require_token_policy_decision: bool = False,
    allow_token_policy_decision: bool = False,
    token_policy_run_id: int | None = None,
) -> dict[str, Any]:
    if not segment_ids:
        return {
            "available": True,
            "candidates": 0,
            "ready": 0,
            "blocked": 0,
            "result_counts": {},
        }
    pipeline_dir = str(ROOT / "pipeline")
    if pipeline_dir not in sys.path:
        sys.path.insert(0, pipeline_dir)
    try:
        import apply_segment_state_updates as segment_apply
    except Exception as exc:  # pragma: no cover - import problem should surface in preflight
        return {
            "available": False,
            "error": str(exc),
            "candidates": 0,
            "ready": 0,
            "blocked": len(segment_ids),
            "result_counts": {"readiness_import_error": len(segment_ids)},
        }

    settings = segment_apply.db.load_settings()
    output_root = segment_apply.db.project_path(settings["output_spanish"])
    with sqlite3.connect(db_path) as con:
        con.row_factory = sqlite3.Row
        selected_run_id = state_run_id or segment_apply.latest_state_run_id(con)
        candidates = segment_apply.fetch_candidates(
            con,
            state_run_id=selected_run_id,
            review_states=segment_apply.parse_review_states("human_locked,human_confirmed", True),
            limit=None,
            path_like=None,
            segment_ids=set(segment_ids),
            include_intentional_blank=True,
            require_token_policy_decision=require_token_policy_decision,
            allow_token_policy_decision=allow_token_policy_decision,
            token_policy_run_id=token_policy_run_id,
        )
    result_counts, _previews = segment_apply.evaluate_best_candidates(
        candidates,
        output_root=output_root,
        allow_locked_token_override=False,
        require_token_policy_decision=require_token_policy_decision,
        allow_token_policy_decision=allow_token_policy_decision,
        include_intentional_blank=True,
    )
    if require_token_policy_decision:
        missing_decision_candidates = max(0, len(segment_ids) - len(candidates))
        if missing_decision_candidates:
            result_counts["missing_token_policy_decision"] += missing_decision_candidates
    ready = (
        int(result_counts.get("ready", 0))
        + int(result_counts.get("ready_preserved_output_token_signature", 0))
        + int(result_counts.get("ready_token_override", 0))
        + int(result_counts.get("ready_token_policy_decision", 0))
        + int(result_counts.get("ready_pairwise_intentional_elision", 0))
    )
    return {
        "available": True,
        "state_run_id": selected_run_id,
        "require_token_policy_decision": require_token_policy_decision,
        "allow_token_policy_decision": allow_token_policy_decision,
        "token_policy_run_id": token_policy_run_id,
        "candidates": len(candidates),
        "ready": ready,
        "blocked": max(0, len(segment_ids) - ready),
        "result_counts": dict(result_counts),
    }


def _write_production_run_status(status: dict[str, Any]) -> bool:
    status["updated_at"] = _now_iso()
    PRODUCTION_RUN_STATUS_FILE.parent.mkdir(parents=True, exist_ok=True)
    status.pop("status_persistence_warning", None)
    status.pop("status_persistence_error_at", None)
    serialized = json.dumps(status, ensure_ascii=False, indent=2) + "\n"
    last_error: OSError | None = None

    # OneDrive and antivirus scanners can briefly hold the destination file on
    # Windows.  Keep the last valid JSON intact, serialize concurrent heartbeat
    # writers, and retry an atomic replace instead of truncating the live file.
    with PRODUCTION_STATUS_WRITE_LOCK:
        for attempt in range(PRODUCTION_STATUS_WRITE_ATTEMPTS):
            temporary_path = PRODUCTION_RUN_STATUS_FILE.with_name(
                f".{PRODUCTION_RUN_STATUS_FILE.name}.{os.getpid()}."
                f"{threading.get_ident()}.{attempt}.tmp"
            )
            try:
                temporary_path.write_text(serialized, encoding="utf-8")
                os.replace(temporary_path, PRODUCTION_RUN_STATUS_FILE)
                return True
            except OSError as exc:
                last_error = exc
                try:
                    temporary_path.unlink(missing_ok=True)
                except OSError:
                    pass
                if attempt + 1 < PRODUCTION_STATUS_WRITE_ATTEMPTS:
                    delay = min(
                        PRODUCTION_STATUS_WRITE_RETRY_SECONDS * (2**attempt),
                        0.5,
                    )
                    time.sleep(delay)

    # Status persistence is telemetry and must not terminate an otherwise safe
    # pipeline command.  A later heartbeat will retry and persist this warning.
    status["status_persistence_warning"] = str(last_error or "status write failed")
    status["status_persistence_error_at"] = _now_iso()
    return False


def _recover_orphaned_production_run_on_startup() -> dict[str, Any]:
    """Close a run whose in-process worker disappeared with the previous API."""
    status = _read_production_run_status()
    if status.get("status") not in {"starting", "running"}:
        return status

    interrupted_at = _now_iso()
    previous_event_at = str(
        status.get("last_event_at")
        or status.get("updated_at")
        or status.get("started_at")
        or ""
    )
    current_stage_id = str(status.get("current_stage") or "")
    current_stage = next(
        (
            stage
            for stage in status.get("stages") or []
            if isinstance(stage, dict)
            and (
                stage.get("id") == current_stage_id
                or (not current_stage_id and stage.get("status") == "running")
            )
        ),
        None,
    )
    if current_stage is not None and current_stage.get("status") in {"pending", "starting", "running"}:
        current_stage["status"] = "cancelled"
        current_stage["finished_at"] = interrupted_at
        current_stage["updated_at"] = interrupted_at
        current_stage["interruption_reason"] = "backend_restarted_without_live_worker"

    status["status"] = "cancelled"
    status["finished_at"] = interrupted_at
    status["interrupted_at"] = interrupted_at
    status["last_worker_event_at"] = previous_event_at
    status["interruption_reason"] = "backend_restarted_without_live_worker"
    status["message"] = "Execução anterior interrompida pelo encerramento do sistema."
    status["current_label"] = "Execução interrompida"
    _append_run_log(
        status,
        "[recovery] Execução órfã encerrada na inicialização; nenhum worker foi retomado.",
    )
    _write_production_run_status(status)
    return status


def _production_run_active() -> bool:
    status = _read_production_run_status()
    return status.get("status") in {"starting", "running"}


